\begin{theorem}[Compact support and rapid decay]
\label{thm:rapid}
Fix a positive computable viscosity $\nu$. From a deterministic Turing machine $M$ and a
finite input $w$ one can effectively construct a smooth force on
$[0,\infty)\times\R^3$, supported for all times in the fixed compact set
\[
 K=[-2,1]\times[-1,2]\times[-1,1],
\]
such that, for every pair of nonnegative integers $J,l$ and spatial
multi-index $\alpha$,
\begin{equation}
 \sup_{t\geq0,\,x\in\R^3}
 (1+t)^J\bigl|\partial_t^l\partial_x^\alpha f(t,x)\bigr|<\infty.
 \label{eq:rapid-force-bound}
\end{equation}
The Navier--Stokes equation with this force and zero initial velocity has
an explicit global smooth solution, unique in the finite-interval class \eqref{eq:energy-class}.  Its material trajectory from
the origin satisfies
\begin{equation}
 M\text{ halts on }w
 \quad\Longleftrightarrow\quad
 X_1(t,0)<-1\text{ for some }t\geq0.
 \label{eq:rapid-event}
\end{equation}
The velocity has the same fixed support and rapid mixed-derivative bounds.
The pressure is zero. The force is a general body force. Because $K$ is fixed,
the same bounds hold with $(1+t+|x|)^J$ in place of $(1+t)^J$.
\end{theorem}

\begin{theorem}[Rapid decay with alternating memories]
\label{thm:alternating}
Fix a positive computable viscosity. From a deterministic Turing machine
and a finite input one can effectively
construct a smooth force $f$ on $[0,\infty)\times\mathbb R^3$, with
spatial support contained in a fixed compact set independent of time,
such that for every $J,l\geq0$ and spatial multi-index $\alpha$,
\begin{equation}
 \sup_{t\geq0,\,X\in\mathbb R^3}
 (1+t+|X|)^J
 |\partial_t^l\partial_X^\alpha f(t,X)|<\infty.
 \label{eq:alternating-schwartz}
\end{equation}
The solution with zero initial velocity is explicit, global, and unique
in the class \eqref{eq:energy-class}, with pressure zero.  Its velocity satisfies
the same support and derivative estimates.  The material particle
initially at $(-1,0,0)$ reaches $X_1>0$ if and only if the machine halts.
\end{theorem}

\begin{lemma}\label{lem:lattice-address}
The functions $F_n,h_n$ on $\mathbb Z$ are $P_n$-periodic,
$h_n\in\{0,1\}$, and $0\le F_n<P_{n+1}$ at every address.
If $c_n$ is a true nonhalting configuration and
$j\equiv c_n\pmod {P_n}$, then $F_n(j)=c_{n+1}$.
\end{lemma}

\begin{lemma}\label{lem:lattice-scales}
For $n\ge0$,
\begin{align}
 P_n&\mid\epsilon_n^{-1},&
 P_n&\mid\epsilon_k/\epsilon_n\quad(0\le k<n),
 \label{eq:lattice-divisibility}\\
 P_{n+1}\epsilon_{n+1}
 &\le\epsilon_n^{\,2^{2n+2}-1}
 \le\epsilon_n^3<\epsilon_n/4.
 \label{eq:lattice-plateau-bound}
\end{align}
Moreover, $\beta_n$ decreases strictly and $\epsilon_n\le2^{-n}$.
\end{lemma}

\begin{corollary}\label{cor:undecidable}
For each of these four experiments, no algorithm decides the particle
event for every force program produced by its construction. This remains
true for the solenoidal mean-zero versions of the two torus experiments.
\end{corollary}

\begin{lemma}[Refined fractal estimate]
\label{lem:fractal}
Let $S\geq1$.  Let $\mathcal Q$ be a collection of distinct unit lattice
cubes in a ball of radius $CS$ in $\R^3$.  Suppose that
\begin{equation}
 \#\{Q\in\mathcal Q:Q\cap B(z,r)\ne\varnothing\}
 \leq\gamma r^2\quad(1\leq r\leq CS),
 \qquad
 \#\{Q\in\mathcal Q:Q\cap B(z,\sqrt S)\ne\varnothing\}
 \leq\lambda_0
 \label{eq:prelim-fractal-counts}
\end{equation}
for all centers $z$, with fixed enlargements of the radius range allowed.
If $v$ has frequency support in a fixed bounded set, then
\begin{align}
 \int_{\bigcup\mathcal Q}|Ev|^2\,dx\,dt
 &\leq C_\epsilon S^\epsilon
       (\gamma\lambda_0S)^{1/3}\|v\|_2^2,
 \label{eq:prelim-fractal-integral}\\
 \sum_{Q\in\mathcal Q}\sup_Q|Ev|^2
 &\leq C_\epsilon S^\epsilon
       (\gamma\lambda_0S)^{1/3}\|v\|_2^2.
 \label{eq:prelim-fractal-sup}
\end{align}
These estimates are uniform under translations of the collection of cubes.
\end{lemma}

\begin{lemma}[Weighted refined estimate]
\label{lem:prelim-weighted}
Let $\nu$ be supported in a ball of radius $CS$, $S\geq1$, and suppose
\begin{equation}
 \nu(B(z,r))\leq mr^2\quad(r\geq1),\qquad
 \nu(B(z,\sqrt S))\leq mSd
 \quad(z\in\supp\nu),
 \label{eq:prelim-weighted-hypotheses}
\end{equation}
where $m,d>0$.  For bounded frequency support,
\begin{equation}
 \int |Ev|^2\,d\nu
 \leq C_\epsilon S^\epsilon mS^{2/3}d^{1/3}\|v\|_2^2.
 \label{eq:prelim-weighted-fractal}
\end{equation}
The same bound holds for
$\sum_Q\nu(Q)\sup_Q|Ev|^2$, summed over unit cubes.  The ball bound alone
gives this conclusion with $d=1$, up to a fixed constant.
\end{lemma}

\begin{lemma}[Multilinear estimates with subpower transversality]
\label{lem:transverse-product}
Suppose three exact extension inputs have bounded frequency supports,
and every triple of their unit directions has determinant at least
$\nu$, where $0<\nu\le1$.  For each $\epsilon>0$ there are $C_\epsilon,M_\epsilon<\infty$
such that, on every ball of radius $S\ge2$,
\begin{equation}\label{eq:transverse-product}
 \int_{B_S}\prod_{i=1}^3|Ev_i(z)|\,dz
 \le C_\epsilon\nu^{-M_\epsilon}S^\epsilon
                         \prod_{i=1}^3\|v_i\|_2.
\end{equation}
The same conclusion holds for the sum over unit lattice cubes in the
ball of $\prod_i\sup_Q|Ev_i|$.  In particular, when $\nu=S^{-o(1)}$
both bounds are $S^{o(1)}\prod_i\|v_i\|_2$.
For weighted tubes of width $\Delta$ in a bounded region, the
corresponding multilinear Kakeya bound is
\begin{equation}\label{eq:transverse-kakeya}
 \int\prod_{i=1}^3
       \left(\sum_T w_i(T)\mathbf1_T\right)^{1/2}
 \le C_\epsilon\nu^{-M_\epsilon}\Delta^{3-\epsilon}
                  \prod_{i=1}^3\left(\sum_Tw_i(T)\right)^{1/2}.
\end{equation}
Here fixed enlargements of tubes and of the ambient region are allowed;
if those enlargements are subpower on a sequence, they cost a subpower.
\end{lemma}

\begin{lemma}[Reduction to weighted incident tubes]
\label{lem:transverse-tubes}
A countersequence to Proposition~\ref{prop:transverse} yields a set
$P$ in a fixed bounded region and three weighted tube families satisfying
\begin{equation}\label{eq:transverse-point-counts}
 |P|=L^{2+o(1)},\qquad
 |P\cap B(z,r)|\le L^{2+o(1)}r^2
             \quad(L^{-1}\le r\le1).
\end{equation}
The points are centers of distinct cubes of side comparable to $L^{-1}$.
The tubes have width $L^{-1+o(1)}$, their coefficient weights obey
$\sum_Tw_i(T)\lesssim1$, and every cross-family direction triple has
determinant at least $L^{-o(1)}$.  At each $p\in P$ there is a retained
incident subfamily of total weight $e_i^*(p)=L^{-4/3+o(1)}$ such that
its normalized weight law satisfies, for fixed $\kappa>0$, $u_0>0$,
\begin{equation}\label{eq:src1}
 \Prob\bigl(\operatorname{dir}T_i\in B(v,L^{-u})\mid X=p\bigr)
       \le L^{-\kappa u+o(1)}
       \qquad(0<u<u_0,\ u\in\mathbb Q).
\end{equation}
This bound is uniform in $p,v$ for each fixed rational $u$.
The retained subfamily may depend on $p$.
\end{lemma}

\begin{lemma}[Additivity and replacement invariance]
\label{lem:transverse-additivity}
Almost surely, simultaneously for every choice of one of the two
tubes in each family,
\[
 F=G_1+G_2+G_3,\qquad G_i'=G_i,\qquad G_i(1)=\tfrac23.
\]
In any block above, including a prefix and with any extra direction
bins in $D$,
\begin{equation}\label{eq:src3}
 \begin{split}
 I(Z_i\mid C,D)&=J_i+O\left(\sum_k\ell_k\right),\\
 I(Z_i,Z_j\mid C,D)&=J_i+J_j+
                       O\left(\sum_k\ell_k\right).
 \end{split}
\end{equation}
The absolute constants in these error bounds are fixed.
\end{lemma}

\begin{lemma}[One common profile]\label{lem:transverse-common-profile}
Almost surely,
\begin{equation}\label{eq:src4}
 G_1=G_2=G_3=:G,\qquad F=3G.
\end{equation}
In particular $0\le\dot G\le1$, $G(1)=2/3$, and $3G(s)\ge2s$.
\end{lemma}

\begin{lemma}[Angular marginal information]\label{lem:transverse-angular-information}
The functions $h_2,h_3$ are nonnegative and nondecreasing on their
rational domains, and almost surely
\begin{equation}\label{eq:transverse-angular-sum}
 h_2(u)+h_3(u)\ge\kappa u\qquad(0<u<u_0,\ u\in\mathbb Q).
\end{equation}
Their values agree with those of marginal coordinate-cell information
at comparable resolution; the analogous joint assertion also holds.
\end{lemma}

\begin{lemma}[Binary derivative]\label{lem:transverse-binary}
For almost every path, $\dot G(s)\in\{0,1\}$ for almost every
$s\in[0,1]$.
\end{lemma}

\begin{lemma}[Finite alternation and a full-to-empty jump]
\label{lem:transverse-finite-jumps}
Almost surely $E$ agrees modulo null sets with a finite union of
intervals and has an interior transition from an interval of full
measure to an interval of zero measure.  For every fixed $\eta>0$
there is a rational block $[s,s+b]$, $0<b<u_0$, on an event of
positive probability, such that
\begin{equation}\label{eq:transverse-jump-block}
 G(s+b)-G(s)=\tfrac b2+O(\eta b),\qquad
 G(s+b/2)-G(s)=\tfrac b2+O(\eta b).
\end{equation}
The absolute error constants can be fixed independently of $\eta$.
\end{lemma}

\begin{lemma}[No full-to-empty block]\label{lem:transverse-no-jump}
For sufficiently small fixed $\eta>0$, the positive-probability
configuration in \eqref{eq:transverse-jump-block} is impossible.
\end{lemma}

\begin{lemma}[Broad saving]\label{lem:sparse-broad}
There is an absolute $c_b>0$ such that, whenever $K\le s^{c_b}$, the
broad part of the functional in a ball of radius $O(s^2)$ satisfies
\begin{equation}\label{eq:sparse-broad}
 \sum_{Q\text{ broad}}\nu(Q)^{2/3}\|V\|_{L^6(Q)}^2
       \lesssim s^{-c_b}m_0^{2/3}s^{4/3}\mathcal E.
\end{equation}
Here $\nu(B(z,r))\le m_0r^2$ for $r\ge1$, and the exact frequency
data for $V$ and each $V_\theta$ have $L^2$ norms at most
$C\mathcal E^{1/2}$.  The implicit constant can depend on this fixed
$C$ but $c_b$ does not depend on packet differentiability.
\end{lemma}

\begin{lemma}[Masks, persistence, and loss bounds]\label{lem:frame-masks}
The masks can be chosen so that
\begin{equation}\label{eq:src15}
 |b_a|\leq\lambda,\qquad
 \|\mathcal L P_ab_a\|_\infty\leq C_1\lambda\Delta^2,
\end{equation}
where $C_1$ is independent of the large fixed $K$.  For every required
fixed derivative order,
\begin{equation}\label{eq:src16}
 \|D_a^rP_ab_a\|_\infty\leq C_{r,K}\lambda\Delta^{2r},
 \qquad
 \int_a\|D_a^rP_ab_a\|_2^2\leq C_{r,K}\Delta^{4r}D.
\end{equation}
The removed pieces obey
\begin{equation}\label{eq:src17}
 \begin{split}
 \|(\partial_x-ia)^sD_a^rd_a\|_1
 &\leq C_{K,r,s}\Delta^{s+2r}\lambda^{-1}\int L_a,\\
 \|(\partial_x-ia)^sD_a^rd_a\|_2^2
 &\leq C_{K,r,s}\Delta^{2s+4r}\int L_a,
 \end{split}
\end{equation}
and, pointwise,
\begin{equation}\label{eq:src18}
 |R_j|\leq C_K\lambda^{-1}W_jL_j.
\end{equation}
All derivative constants are uniform in the stage number.
\end{lemma}

\begin{lemma}[Low-frequency flux]\label{lem:frame-flux}
For a smooth spatial projection $\operatorname{Proj}_r$ to
$|\xi|\asymp r$, where $r\lesssim\Delta_j$,
\begin{equation}\label{eq:src20}
 \|\operatorname{Proj}_rW_j\Phi_j\|_2^2
 \leq C_K\lambda^2(r/\Delta_j)l_j.
\end{equation}
\end{lemma}

\begin{lemma}[Quartic control of the growth bands]
\label{lem:frame-quartic}
Let $G_j(u)=\exp(-cu^2/\Delta_j^2)$, for a fixed $c>0$.
Then
\begin{equation}\label{eq:src22}
 \sum_{j=1}^n\int_{\R^2}(G_j-G_{j-1})(u)
       |\widehat{|g_{j-1}|^2}(u,\tau)|^2\,du\,d\tau
 \lesssim_K\lambda^2D.
\end{equation}
\end{lemma}

\begin{lemma}[Maximal recovery of the error fields]
\label{lem:frame-maximal}
The partial errors obey \eqref{eq:src19}.  If $\mathcal M$ is the
spacetime Hardy--Littlewood maximal operator, then also
\begin{equation}\label{eq:src23}
 |Y_k(z')|\lesssim
 (1+\Delta_k|z-z'|)^C\mathcal M(\sup_j|Y_j|)(z)+C_K\lambda^2.
\end{equation}
\end{lemma}

\begin{proposition}[One-dimensional flat estimate]\label{prop:oned}
Let $\nu$ be a nonnegative measure supported in a spatial interval of
length $O(L^2)$ and in $|t|\leq L^2$.  Suppose that, for every
$t_0,b\in\R$, every $v\in I$, and every $1\leq\rho\leq r\leq L^2$,
\begin{equation}\label{eq:flat-tube-test}
 \nu\bigl\{(x,t): |t-t_0|\leq r,
                 \ |x-b-2vt|\leq\rho\bigr\}
       \leq m_1 r\left(1+\frac{\rho}{L}\right).
\end{equation}
There is an exponent $p_0>2$, for which one may take $p_0=21/10$, such
that every array \eqref{eq:flat-oned-field} and every $g>0$ satisfy
\begin{equation}\label{eq:src9}
 \nu\{|V|\geq gL^{-5/6}\}
       \leq C m_1 L^3 g^{-p_0}\|c\|_2^{p_0}.
\end{equation}
The constant is uniform in $L$, in the number of packets, and in their
real centers.  In particular, no factor growing with $L$ is allowed.
\end{proposition}

\begin{proposition}[Thin-strip estimate]\label{prop:strip}
Let $U$ be a finite two-dimensional packet array of the form
\eqref{eq:src5}, with the fixed profile and phase-space bounds stated
there.  Suppose all frequency labels lie within distance $C/L$ of an
affine line in frequency space.  Let $\mu$ be supported in a spatial
square of side $O(L^2)$ and in $|t|\leq L^2$, and suppose
$\mu(B_r)\leq mr^2$ for every ball with arbitrary center and every
$r\geq1$.  Then, with the exponent $p_0$ of
Proposition~\ref{prop:oned},
\begin{equation}\label{eq:src10}
 \mu\{|U|\geq gL^{-4/3}\}
       \leq C mL^4g^{-p_0}\|c\|_2^{p_0},\qquad g>0.
\end{equation}
The constant depends only on the fixed bounds, including the strip
width constant.  No sparsity hypothesis is required.
\end{proposition}

\begin{lemma}[A truncated parameter energy]\label{lem:geometry-energy}
Let $H\geq1$ and let $\sigma$ be a finite measure on $\R^2$ of mass
$m$, satisfying
\[
 \sigma(B(z,r))\leq A r^{1+\eta}
 \qquad(z\in\R^2,\ r\geq H^{-1}),\qquad A>0.
\]
Set $\gamma=\eta/(1+\eta)$. Then
\begin{equation}\label{eq:geometry-parameter-energy}
 \iint \min\{H,|z-z'|^{-1}\}\,d\sigma(z')\,d\sigma(z)
 \leq C_\eta A^{1/(1+\eta)}m^{1+\gamma},
\end{equation}
where the kernel on the diagonal is $H$.
\end{lemma}

\begin{lemma}[Cap gain]\label{lem:dyadic-cap-gain}
For any subarray in a frequency square of side comparable to $r$, where
$L^{-1}\lesssim r\leq\delta_0$, outer induction gives
\begin{equation}\label{eq:dyadic-cap-gain}
 \mu\{|U_{\mathcal C}|\geq r^\eta\lambda\}
 \leq C_{\rm cap}C_{\rm ind}mL^4g^{-p}
 r^{1-p/3-p\eta}
 \Big(\sum_{\alpha\in\mathcal C}|c_\alpha|^2\Big)^{p/2}.
\end{equation}
The estimate holds for any submeasure of $\mu$, with the same upper ball
parameter.  At the smallest scales choose comparable squares so that
the child packet size is at least $1$.
\end{lemma}

\begin{lemma}[Flattened energy estimates]\label{lem:dyadic-flattening}
For a time interval $J$ of length $h^2$, let $\mathcal T(J)$ denote the
boundedly many native time-cell layers that can contribute on $J$.
Summing over the disjoint fine arrays, and also over clusters when
needed, one has
\begin{equation}\label{eq:src13}
 \begin{aligned}
 \sum_{\theta,\,T\in\mathcal T(J)}s_{\theta,T}^2
     &\lesssim h^{-2},\\
 \sum_{\theta,T}d(T)^{2/3}s_{\theta,T}^2
     &\lesssim_B h^{-2}a^{4/3}D^{-c_s}.
 \end{aligned}
\end{equation}
The right sides are multiplied by the total original coefficient
energy if it is not normalized to be at most $1$.
\end{lemma}

\begin{lemma}[Frame estimate for one tuple]\label{lem:dyadic-tuple}
For every tuple remaining after \eqref{eq:dyadic-small-mass},
\begin{equation}\label{eq:dyadic-frame-substitution}
 M_0\lesssim \delta_0^{-C}mh
 \frac{B_1^2B_2^2}{A_{\ell_1}^2A_{\ell_2}^2}
 \left(\frac{h^3E_1}{A_{\ell_1}^2}
            +\frac{h^3E_2}{A_{\ell_2}^2}\right).
\end{equation}
In particular,
\begin{equation}\label{eq:dyadic-cubic-mass}
 \lambda^6M_0^3\lesssim
 \delta_0^{-C}(1+\ell_1+\ell_2)^C
 m^3h^{10}d_1d_2E_1E_2(E_1+E_2).
\end{equation}
\end{lemma}

\begin{proposition}[Short-time maximal estimate]
\label{prop:shortmax}
Let $p>2$ be the exponent in Theorem~\ref{thm:distribution}.  Fix
$0<c_0<C_0<\infty$.  If $N\ge1$ is dyadic and
\[
 \supp\widehat f_N\subset
 \{\xi\in\R^2:c_0N\le |\xi|\le C_0N\},
\]
then, on every unit ball $B\subset\R^2$,
\begin{equation}
 \left\|\sup_{0<t<1/N}|S(t)f_N|\right\|_{L^{p,\infty}(B)}
 \le C N^{1/3}\|f_N\|_2.
 \label{eq:src24}
\end{equation}
The same estimate holds on every translated time interval of length at
most $1/N$, with either endpoint included.
\end{proposition}

\begin{lemma}[Separation in time]
\label{lem:endpoint-time-separation}
Let $\mathcal D_j$ be the dyadic partition of $[0,1)$ into intervals of
length $2^{-j}=1/N$.  Then
\begin{equation}
 e_j([0,1))\le C\sum_{I\in\mathcal D_j}e_j(I)+CN^{-2}.
 \label{eq:endpoint-time-almost-orthogonality}
\end{equation}
\end{lemma}

\begin{lemma}[Mass and spatial localization]
\label{lem:endpoint-localized-dual}
If $I\in\mathcal D_j$ and $J\subset I$ is a dyadic descendant at relative
depth $k$, where $0\le k\le j$, set $r=2^{-k}$.  Then
\begin{align}
 e_j(J)&\le C m_J^{2-2/p},
 \label{eq:endpoint-mass-bound}\\
 e_j(J)&\le C r^{2/3}m_J.
 \label{eq:endpoint-spatial-bound}
\end{align}
Consequently, with
\[
 \alpha=\frac32-\frac1p=1+\frac{1-2/p}{2}>1,
\]
we have
\begin{equation}
 e_j(J)\le C2^{-k/3}m_J^\alpha.
 \label{eq:endpoint-interpolated-dual}
\end{equation}
\end{lemma}

\begin{lemma}[Summation on the common time tree]
\label{lem:endpoint-square-sum}
For every graph and phase choice in
\eqref{eq:endpoint-dual-definitions},
\begin{equation}
 \sum_{j\ge1}2^{-2j/3}\|G_{2^j}([0,1))\|_2^2\le C.
 \label{eq:endpoint-square-sum}
\end{equation}
The constant is independent of $t$, $w$, and the center of $\Omega$.
\end{lemma}

\begin{theorem}[Local strong maximal estimate]
\label{thm:maximal}
There is a constant $C$ such that, for every $f\in H^{1/3}(\R^2)$ whose
Fourier transform has compact support and every $x_0\in\R^2$,
\begin{equation}
 \int_{B(x_0,1)}\sup_{0\le t<1}|S(t)f(x)|\,dx
       \le C\|f\|_{H^{1/3}}.
 \label{eq:endpoint-strong-maximal}
\end{equation}
For arbitrary $f\in H^{1/3}(\R^2)$ there is a jointly measurable
representative $v_f(x,t)$, $0\le t<1$, continuous in $t$ for almost every
$x$, equal to $S(t)f$ as an $L^2$ function for each fixed $t$, and satisfying
the same bound with $S(t)f(x)$ replaced by $v_f(x,t)$.
\end{theorem}

\begin{proposition}[Lossless short-time weak estimate]
\label{e:short-time}
Let $p>2$ be the exponent in \Cref{w:weak}.  If $N\ge1$ and $f_N\in L^2$
has Fourier support in a fixed annulus dilated by $N$, then for every
unit ball $\Omega\subset\R^n$ and every time interval $I$ of length
$N^{-1}$,
\begin{equation}
 \left\|\sup_{t\in I}|S(t)f_N|\right\|_{L^{p,\infty}(\Omega)}
       \le C N^s\norm{f_N}_2.
 \label{e:short-formula}
\end{equation}
The constant is independent of the centers of $\Omega$ and $I$.
\end{proposition}

\begin{lemma}[Dual square sum]
\label{e:dual-square}
Fix measurable $t:\Omega\to[0,1)$ and $w:\Omega\to\C$ with $|w|\le1$,
where $\Omega$ is a unit ball.  Let $\psi$ be a smooth compactly
supported annular cutoff.  For $N=2^j$, $j\ge1$, and a half-open dyadic
interval $I\subset[0,1)$ set
\[
 G_N(I)(\xi)=\psi(\xi/N)
    \int_{\{x\in\Omega:t(x)\in I\}}
         e^{ix\cdot\xi-it(x)|\xi|^2}w(x)\dd x,
 \qquad d_j(I)=N^{-2s}\norm{G_N(I)}_2^2.
\]
Then
\begin{equation}
 \sum_{j\ge1}d_j([0,1))\le C.
 \label{e:dual-square-formula}
\end{equation}
The same $t$ and $w$ are used for every $j$.
\end{lemma}

\begin{theorem}[Local $L^1$ endpoint maximal estimate]
\label{e:maximal}
For compactly supported $\widehat f\in L^2$ and every unit ball $\Omega$,
\begin{equation}
 \int_\Omega\sup_{0\le t<1}|S(t)f(x)|\dd x
       \le C\norm{f}_{H^s(\R^n)}.
 \label{e:maximal-formula}
\end{equation}
The constant is uniform under translation of $\Omega$.
\end{theorem}

\begin{lemma}[Energy budgets after flattening]\label{w:flatten}
For each physical time bin of length $h^2$, including its fixed
enlargement,
\begin{equation}\label{w:eq-flat-unweighted}
 \sum_{\mathrm{bin}}s_{\theta,T}^2\lesssim h^{-n}.
\end{equation}
There is also the global bound, summed over all clusters, fine bins,
cells and time bins with bounded overlap,
\begin{equation}\label{w:eq-flat-weighted}
 \sum_{\theta,T}d_{\theta,T}^{\beta}s_{\theta,T}^2
 \lesssim_B h^{-n}b_1^{2n/(n+1)}D^{-c_s}.
\end{equation}
The first assertion is only a per-time-bin statement.
\end{lemma}

\begin{lemma}[A tuple bound]\label{w:tuple}
For each retained tuple,
\begin{equation}\label{w:eq-tuple}
 \lambda^2 M_0\leq CR^C(1+\textstyle\sum_i\ell_i)^C
 m\chi^{1-\beta}h^{n+2n/(n+1)}
 \left(\prod_{i=1}^n d_{\ell_i}E_i\right)^{\beta/n}
 \left(\sum_{i=1}^nE_i\right)^{1-\beta}.
\end{equation}
The $R$ exponent is independent of the number of plate clusters and
time bins and of $C_{10},C_{11}$.
\end{lemma}

\begin{definition}[Normalized compact arrays and admissible measures]
\label{d:measure}
A compact array of scale $L\ge1$ is a finite sum
\begin{equation}
 U(x,t)=\sum_\alpha c_\alpha L^{-n/2}
 e^{i(x\cdot\omega_\alpha-t|\omega_\alpha|^2)}
 \phi_\alpha\!\left(
     \frac{x-y_\alpha-2t\omega_\alpha}{L},\frac t{L^2}\right).
 \label{d:array}
\end{equation}
The frequencies $\omega_\alpha$ belong to a fixed bounded box.
The native profiles $\phi_\alpha$ are supported in a fixed box and have
uniform bounds for derivatives through a prescribed sufficiently large
finite order.  The number of labels
$(L\omega_\alpha,y_\alpha/L)$ in every unit phase-space ball is
bounded by a fixed constant.  Its coefficient energy is
$E(U)=\sum_\alpha|c_\alpha|^2$.
Subarrays retain their original profiles and labels.

A nonnegative Borel measure $\mu$ has $n$-dimensional growth with
parameter $m$ if
\begin{equation}
 \mu(B(z,r))\le m r^n\qquad(z\in\R^{n+1},\ r\ge1).
 \label{d:ball-growth}
\end{equation}
At array scale $L$ its native time range is bounded by a fixed
constant, so $\supp\mu\subset\{|t|\le C L^2\}$ after a common time
translation.  Fix a sufficiently large $M$.  The tube moment condition
with sparsity parameter $D$ is
\begin{equation}
 \int\left(1+
       \frac{|x-y_\alpha-2\omega_\alpha t|}{L}\right)^{-M}
          \dd\mu(x,t)
       \le \frac{mL^{n+1}}D
       \quad\text{for every included label }\alpha.
 \label{d:tube-moment}
\end{equation}
We use half-open unit cubes for all measure sums, so their masses add
without boundary ambiguity.
\end{definition}

\begin{theorem}[Du--Zhang input in squared form]
\label{d:dz-input}
Let $\mathcal Q$ be a collection of distinct unit lattice cubes in a
ball of radius $S\ge1$.  Suppose their counting function in every ball
of radius $r\ge1$ is at most $\Gamma r^n$, and their number in any ball
of radius $\sqrt S$ is at most $\lambda_0$.  Then for every $\eps>0$,
\begin{equation}
 \sum_{q\in\mathcal Q}\sup_q|\mathcal E g|^2
 \le C_\eps S^{\eps}
       \Gamma^{4/((n+1)(n+2))}\lambda_0^{\gamma_n}
       S^{\gamma_n}\norm{g}_2^2.
 \label{d:dz-sup}
\end{equation}
All fixed enlargements and translations of the cube lattice are
allowed, with fixed changes of the constant.
\end{theorem}

\begin{proposition}[Weighted fractal norm and occupancy gain]
\label{d:fractal}
\label{d:refined}
Suppose $\mu$ is supported in a ball of radius $CS$, satisfies
\eqref{d:ball-growth}, and, in addition,
\begin{equation}
 \mu(B(z,\sqrt S))\le d\,m S^{n/2},
 \qquad S^{-A_0}\le d\le1.
 \label{d:sqrt-occupancy}
\end{equation}
Then
\begin{equation}
 \sum_q\mu(q)^\beta\sup_q|\mathcal E g|^2
 \le C_{\eps,A_0}\,m^\beta
       S^{n/(n+1)+\eps}d^{\gamma_n}\norm{g}_2^2.
 \label{d:weighted-fractal}
\end{equation}
With $d=1$ no extra assumption beyond growth is needed.  The estimate
is homogeneous in $\mu$ and in the squared input norm.
\end{proposition}

\begin{corollary}[Power-loss norm for compact arrays]
\label{d:power-loss}
Let $U$ be a compact array of scale $L$, and let $\mu$ satisfy
\eqref{d:ball-growth} in a spacetime box of side $O(L^2)$.
For every $\eps>0$, with sufficiently many fixed profile derivatives,
\begin{equation}
 \sum_q\mu(q)^\beta\sup_q|U|^2
       \le C_\eps m^\beta L^{2n/(n+1)+\eps}E(U).
 \label{d:compact-fractal}
\end{equation}
\end{corollary}

\begin{lemma}[Decoupling inside a strip]
\label{d:strip-decoupling}
Group a field $V=\sum_\theta V_\theta$ by frequency-label bins of side
$K^{-1}$.  Suppose the field supports lie in fixed enlargements of
these bins and within vertical Fourier distance $O(K^{-2})$ of the
paraboloid.  If the labels lie within $O(K^{-1})$ of an affine
$j$-plane, $1\le j\le n$, and $2\le P\le q_j=2(j+2)/j$, then
\begin{equation}
 \norm{V}_{L^P(Q)}^2
 \le C_{\eps,A}K^\eps
       \sum_\theta\sum_{a\in\Z^{n+1}}\braket{a}^{-A}
                 \norm{V_\theta}_{L^P(Q+K^2a)}^2.
 \label{d:local-strip-decoupling}
\end{equation}
The constituent fields may be arbitrary prescribed subfields with
these supports.  Without the strip hypothesis the same estimate holds
with the factor $CK^n$ in place of $C_\eps K^\eps$.
\end{lemma}

\begin{lemma}[Coarse norm transport]
\label{d:transport}
Let $F=X_{K,v}$ with bounded $v$, and suppose
$V(z)=K^{-n/2}e^{i\varphi(z)}V'(Fz)$ with $|e^{i\varphi}|=1$.
For a fixed $a\in\Z^{n+1}$,
\begin{equation}
 \sum_Q\nu(Q)^b\norm{V}_{L^P(Q+K^2a)}^2
 \le C K^{2-(n+2)b}\sum_{r,s\in\mathcal R}
                 \mathcal T_b(V',\nu_{a,r,s}),
 \label{d:transport-functional}
\end{equation}
where $\mathcal R$ is a fixed finite set, independent of $Q,K,a$, and
\begin{equation}
 \nu_{a,r,s}
  =(\tau_{F(K^2a)+K^2(s-r)})_\# F_\#\nu,
 \qquad \tau_h(z)=z+h.
 \label{d:translated-measures}
\end{equation}
Their translations have size at most $CK^2(1+|a|)$.  The same conclusion
holds with any prescribed subset of parent cubes on the left.
If $\nu$ has growth parameter $m$, each child measure has parameter
$CmK^{n+1}$.  Direct pushforward transports
\eqref{d:tube-moment} from scale $L$ to $L/K$ with the same $D$.
\end{lemma}

\begin{lemma}[Profiles]\label{f:profiles}
After taking subsequences and finer finite rational grids there are
nonnegative, nonincreasing, $k/2$-Lipschitz functions $f_i$ such that
\[
 r_{i,s}=\Lambda^{f_i(s)+o(1)},\qquad f_i(e_i)=0.
\]
In the power case $f_i(0)=\lim\log_h A_i$. In the subpower case
\begin{equation}\label{f:d-bounded}
 0\le d_i(s):=f_i(s)+ks/2\le ke_i/2\qquad(s\le0).
\end{equation}
\end{lemma}

\begin{lemma}[Restricted path law]\label{f:paths}
For the selected tree, and for each of the directional restrictions
constructed below, one can draw a uniform root point $Z$ from a
subpower fraction of $Y$ and then a path to a fine direction $\Omega_i$
in each field. The intermediate active cells lie within subpower
normalized distance of $Z$. The fields' paths may be drawn
independently conditional on $Z$.

For the reference cap square weights just defined, at a typical
sampled label
\begin{equation}\label{f:cap-law}
 \Pr(\tau\mid Z)=\Lambda^{o(1)}b_\tau^2(Z).
\end{equation}
Let $T_s(Z,\Omega_i)$ be the cell containing $Z$ in the disjoint
scale-$\kappa_i(s)$ lattice tilted by $\Omega_i$. At a typical draw,
\begin{equation}\label{f:occupancy-law}
 \frac{\Pr(T_s(Z,\Omega_i)\mid\Omega_i)}
      {\Pr(Z\mid\Omega_i)}=\Lambda^{o(1)}M_{i,s}.
\end{equation}
Typical means outside probability tending to zero on each fixed
finite test, with any prescribed positive exponent tolerance.
\end{lemma}

\begin{proposition}[Binary slope rigidity]\label{f:binary}
Every profile satisfies
\begin{equation}\label{f:binary-eq}
 f_i'(s)\in\{0,-k/2\}\quad\text{for almost every }s.
\end{equation}
\end{proposition}

\begin{lemma}[Vanishing left limit]\label{f:left-limit}
In the subpower case,
\begin{equation}\label{f:left-limit-eq}
 \lim_{s\to-\infty}d_i(s)=0
 \quad\text{for every }i.
\end{equation}
Consequently $f_i(0)=0$, including when $e_i=0$.
\end{lemma}

\begin{proposition}[Robust hyperplane projection input]\label{p:projection}
Fix $d\geq2$, $0<\alpha<d$, and $\rho>0$.  There are positive constants
$\eta_0,\gamma$ and $\Delta_0$ with the following consequence.  If
$0<\eta\leq\eta_0$, $0<\Delta<\Delta_0$, $A$ lies in a fixed unit ball,
\[
 \Delta^{-\alpha+\eta}\leq\mathcal N_\Delta(A)
 \leq\Delta^{-\alpha-\eta},\qquad
 \mathcal N_\Delta(A\cap B(x,r))
 \leq\Delta^{-\eta}r^\rho\mathcal N_\Delta(A)
 \quad(\Delta\leq r\leq1),
\]
and $\nu$ is a probability law on unit kernel directions satisfying
\begin{equation}\label{p:projection-angular}
 \nu\{v:|v\cdot w|<r\}\leq\Delta^{-\eta}r^\rho
 \quad(|w|=1,\ \Delta\leq r\leq1),
\end{equation}
then some direction in the support of $\nu$ has
\begin{equation}\label{p:projection-conclusion}
 \mathcal N_\Delta(\pi_{v^\perp}A')
 \geq\Delta^{-(d-1)\alpha/d-\gamma}
 \quad\text{for every }A'\subset A\text{ with }
 \mathcal N_\Delta(A')\geq\Delta^\eta\mathcal N_\Delta(A).
\end{equation}
Fixed multiplicative constants and bounded affine normalizations in the
hypotheses are allowed after reducing $\eta_0,\gamma$.
\end{proposition}

\begin{lemma}[Reproduction, tails, and unit suprema]\label{p:reproduction}
For the band-limited class in \Cref{p:conventions}, the following operations
are uniform in the size of the packet family.

\begin{enumerate}
\item A polynomially decaying packet is an absolutely convergent sum of packets
with the same fixed enlarged native Fourier support and arbitrarily rapid
Schwartz decay about translated native centers.  The coefficient at a
translation $j\in\Z^{k+1}$ is at most
$C_A s_T(1+|j|)^{-P'}$, where $A$ is the requested output decay order.
\item All fixed native derivative orders satisfy the corresponding envelope
bounds.  If $F$ has Fourier support in a fixed bounded set and $r>0$, then,
for every sufficiently large fixed $L$,
\begin{equation}\label{p:sup-convolution}
 \sup_{|u-z|\leq C}|F(u)|^r
 \leq C_{r,L}\int |F(y)|^r(1+|y-z|)^{-L}\dd y.
\end{equation}
\end{enumerate}
Consequently integral packet estimates below also hold with unit-cube
suprema, or with separate unit suprema for factors of a product.  Output
Schwartz orders may be chosen after a small loss parameter; the original
exponent $P'$ and original smooth-profile derivative order stay fixed.
\end{lemma}

\begin{proposition}[Local linear estimate]\label{p:local-linear}
Let $V=\sum_Tf_T$ be either a band-limited or a smooth packet field of scale
$N$, and let $B^2=\sum_Ts_T^2w_T$.  For a ball $D$ of radius $N$ and any
$z_0\in D$,
\begin{equation}\label{p:local-linear-equation}
 \|V\|_{L^{q_k}(D)}\leq C N^{k/2}B(z_0).
\end{equation}
The same bound holds for the unit-supremum norm on $D$.
\end{proposition}

\begin{proposition}[Local multilinear estimate]\label{p:local-multilinear}
Let $V_j$ and $B_j$ be as in \Cref{p:local-linear}, with frequency labels
in sets satisfying \eqref{p:transversality}.  For fixed $p>p_k$, a ball $D$
of radius $N$, and arbitrary points $z_j\in D$,
\begin{equation}\label{p:local-multilinear-equation}
 \left\|\prod_{j=1}^{k+1}|V_j|^{1/(k+1)}\right\|_{L^p(D)}
 \leq C_p\delta^{-C_p}N^{k/2}
 \prod_{j=1}^{k+1}B_j(z_j)^{1/(k+1)}.
\end{equation}
Separate unit suprema may be taken for the $k+1$ factors.  In particular the
constant has no $N^\eps$ factor.
\end{proposition}

\begin{lemma}[Sampling preserves the envelope exponent]\label{p:convolution}
Let $K'\geq K\geq1$, let a $K'$-cap lie in a $K$-cap, and let $T'$ be a
child cell of scale $K'$.  If $\mathcal G_K$ is the parent grid in that cap,
then, for $P>k+2$ sufficiently large,
\begin{equation}\label{p:convolution-equation}
 \sum_{T\in\mathcal G_K}w_T(z)w_{T'}(z_T)\leq C_Pw_{T'}(z).
\end{equation}
The same exponent $P$ occurs on both sides, independently of $K'/K$.
If the sum is restricted to $d_T(z)>L$, $L\geq2$, it is at most
\begin{equation}\label{p:convolution-tail}
 C_P\left(L^{-(P-k-1)}+(K/K')^{P-k-2}\right)w_{T'}(z).
\end{equation}
When $d_{T'}(z)$ is bounded, the second term can be omitted.
\end{lemma}

\begin{lemma}[A polynomial starting bound]\label{p:polynomial-start}
Under the hypotheses of \Cref{p:near-cauchy}, there is a fixed finite $M_k$
such that
\begin{equation}\label{p:polynomial-start-equation}
 |Y|\leq C(2+R)^{M_k}\sum_Ts_T^2.
\end{equation}
\end{lemma}

\begin{lemma}[The geometric alternative]\label{s:simplex}
For a fixed sufficiently large $C_0$, either all active centers lie
within $C_0/K$ of an affine hyperplane, or $n+1$ active bins have
direction determinant at least $cK^{-n}$ throughout their exact
supports.  A common frequency shift does not affect this alternative.
\end{lemma}

\begin{lemma}[Broad gain]\label{s:broad}
There exists $c_b>0$, depending only on the fixed frequency box and
$n$, such that if $K\le l^{c_b}$, then in every box of side $O(l^2)$,
\begin{equation}\label{s:broad-bound}
 \sum_{Q\text{ broad}}\nu(Q)^\beta\norm V_{L^P(Q)}^2
       \lesssim m_0^\beta l^{2n/(n+1)-c_b}\mathcal E_0.
\end{equation}
Here $\nu(B(z,r))\le m_0r^n$ for $r\ge1$, and the input squared
norms of the total field and every subfield are at most $C\mathcal E_0$.
The fixed $C$ may affect the implicit constant, but the gain is
independent of packet differentiability and decay orders.
\end{lemma}

\begin{proposition}[Transverse saving]\label{t:transverse}
Fix a bounded frequency region in $\R^n$.  There are $c>0$ and
$L_0<\infty$, depending only on this region and $n$, such that the
following configuration is impossible for $L\ge L_0$.  Let
$\mathcal Q$ be distinct unit lattice cubes in a ball of radius $L^2$
in $\R^{n+1}$, with
\begin{equation}\label{t:forbidden-counts}
 \#\mathcal Q\ge L^{2n-c},\qquad
 \#\{q\in\mathcal Q:q\cap B(z,r)\ne\varnothing\}
       \le L^c r^n\quad(r\ge1).
\end{equation}
Suppose $f_1,\ldots,f_{n+1}$ have $L^2$ norm at most one, frequency
support in the fixed region, and
\[
 \sup_q|Ef_i|\ge L^{-e-c}
       \quad(q\in\mathcal Q,\ 1\le i\le n+1).
\]
It is impossible that every choice of one frequency from each support
has direction determinant at least $L^{-c}$ in absolute value.
\end{proposition}

\begin{lemma}[Multilinear estimates with polynomial dependence]
\label{t:multilinear}
If $n+1$ bounded-frequency exact inputs are transverse with determinant
at least $\nu\in(0,1]$, then, for each $\eps>0$,
\begin{equation}\label{t:multilinear-extension}
 \sum_{q\subset B_S}\prod_{i=1}^{n+1}
       \bigl(\sup_q|Ef_i|\bigr)^{2/n}
 \le C_\eps\nu^{-M_\eps}S^\eps
                    \prod_{i=1}^{n+1}\norm{f_i}_2^{2/n}.
\end{equation}
The same bound holds with the sum replaced by the integral of the
product.  For transverse families of tubes of width $\delta$ in a fixed
bounded region, with nonnegative weights $w_i(T)$, the corresponding
Kakeya bound is
\begin{equation}\label{t:kakeya}
 \int\prod_{i=1}^{n+1}
       \left(\sum_Tw_i(T)\mathbf1_T\right)^{1/n}
 \le C_\eps\nu^{-M_\eps}\delta^{n+1-\eps}
             \prod_i\left(\sum_Tw_i(T)\right)^{1/n}.
\end{equation}
Fixed enlargements are allowed.  Subpower enlargements and
$\nu=S^{-o(1)}$ give only subpower losses.
\end{lemma}

\begin{lemma}[Pruned incident-tube model]\label{t:tubes}
A countersequence to Proposition~\ref{t:transverse} yields a set
$\mathcal P$ of centers of distinct $L^{-1}$-scale cubes in a bounded
region, satisfying
\begin{equation}\label{t:point-counts}
 \#\mathcal P=L^{n+o(1)},\qquad
 \#(\mathcal P\cap B(z,r))\le L^{n+o(1)}r^n
                     \quad(L^{-1}\le r\le1),
\end{equation}
and $n+1$ transverse weighted tube families of width $L^{-1+o(1)}$.
Their weights satisfy $\sum_Tw_i(T)\lesssim1$.  For every $x\in\mathcal P$
there is an incident subfamily of retained weight
$w_i^*(x)=L^{-e+o(1)}$ whose normalized law satisfies
\begin{equation}\label{t:strip-law}
 \mathbb P\{\xi(T_i)\in N_{L^{-\alpha}}(H)\mid X=x\}
       \le L^{-c_1\alpha+o(1)}
\end{equation}
for every affine $(n-2)$-plane $H\subset\R^n$ and every fixed rational
$0<\alpha<1/8$.  Here $c_1>0$ is fixed independently of $\alpha$, and
the estimate is uniform in $x,H$ for each fixed $\alpha$.
\end{lemma}

\begin{lemma}[One common profile]\label{t:common}
Almost surely all $n+1$ conditional profiles coincide:
\begin{equation}\label{t:common-profile}
 G_i=G_i'=G,\qquad F=(n+1)G,\qquad
 0\le\dot G\le1,\quad G(1)=\frac n{n+1},\quad
 (n+1)G(s)\ge ns.
\end{equation}
\end{lemma}

\begin{lemma}[Binary derivative and finite alternation]\label{t:alternation}
Almost surely $\dot G\in\{0,1\}$ almost everywhere, and
$E=\{s:\dot G(s)=1\}$ agrees modulo null sets with a finite union of
intervals.  There is an interior full-to-empty transition.  Consequently,
for every fixed $\eta>0$, some rational block $[s,s+b]$ with $0<b<1/8$
satisfies, on an event of positive probability,
\begin{equation}\label{t:jump}
 G(s+b)-G(s)=b/2+O(\eta b),\qquad
 G(s+b/2)-G(s)=b/2+O(\eta b).
\end{equation}
\end{lemma}

\begin{lemma}[No full-to-empty block]\label{t:no-jump}
For sufficiently small fixed $\eta>0$, the positive-probability event
in \eqref{t:jump} is impossible.
\end{lemma}

\begin{lemma}[Reduction to broad heavy incidences]\label{w:heavy-reduction}
There is a subset $Y'\subset Y$ with $\mu(Y')\geq cM_Y$ such that,
at each point of $Y'$:
\begin{enumerate}[label=\textup{(\roman*)}]
\item the heavy-bin field has modulus at least $\lambda/2$;
\item the heavy-bin centers are not contained in a strip of any fixed
large constant times $R^{-1}$ about an affine $(n-2)$-plane, nor in a
single quadratic neighborhood of the form in \Cref{w:angular};
\item every heavy bin supplies at least $W/2$ of its weighted
coefficient square mass from trajectories within distance $X^{C_w}L$.
\end{enumerate}
In particular some $n$ heavy bins have direction vectors
$(2\omega,1)$ whose $n$-volume is at least $R^{-C}$ throughout the
bins.
\end{lemma}

\begin{lemma}[Incidence mass and a wall]\label{w:wall}
The preceding level set satisfies
\begin{equation}\label{w:eq-incidence-mass}
 N_YW^{n/(n-1)}\leq X^C,
 \qquad N_Y\geq X^{-C}L^n.
\end{equation}
Moreover, a subset of $Y'$ of mass comparable to $N_Y$ lies within
distance $X^C$ of the zero set of a polynomial of degree at most
$X^{C_{\mathrm{part}}}$ in tube coordinates.
\end{lemma}

\begin{lemma}[Line tests]\label{w:line-tests}
For any prescribed large $A$, choose a fixed $C_6$ sufficiently large.
For every label, outside polynomially many macroscopic time intervals
of total length at most $X^{-A}$, an incidence with any eligible $p$
satisfies
\begin{equation}\label{w:eq-line-tests}
 |v_j-\nabla\phi(p)\cdot\bar v|\leq X^{C_6}/L,
 \qquad |\nabla^2\phi(p)[\bar v,\bar v]|\leq X^{C_6}/L,
 \qquad v=(2\omega,1).
\end{equation}
The exponent bounding the number of intervals is independent of the
sizes of $A,C_6$.
\end{lemma}

\begin{proposition}[Affine plate covering]\label{w:geometry}
A subset $Y_0\subset Y'$ with $\mu(Y_0)\gtrsim M_Y$ is contained
in a union of at most $X^C$ affine hyperplane plates, each of thickness
$X^C$ in tube coordinates.
\end{proposition}

\begin{assumption}\label{ass:kinetic}
The function \(f_0\ge0\) is a smooth probability density and, for some
\(\beta>0\),
\begin{equation}\label{eq:initial-bol-bounds}
 \|f_0\|_{\Bol,2\beta}
 +\|\nabla_xf_0\|_{\Bol,2\beta}<\infty.
\end{equation}
There is a nonnegative classical solution \(f\) of \eqref{eq:boltzmann} with initial
datum \(f_0\) on a prescribed finite interval \([0,T]\), \(T>0\), such that
\begin{equation}\label{eq:kinetic-gaussian}
 M:=\sup_{0\le t\le T}\sup_{x,v}
       e^{2\beta|v|^2}f(t,x,v)<\infty.
\end{equation}
\end{assumption}

\begin{theorem}[Finite-dimensional fluctuation limit]\label{thm:main}
Under \Cref{ass:kinetic}, the centered Gaussian generalized field
\(\zeta\) with weak equation
\begin{equation}\label{eq:fluctuating-equation}
 \dd\zeta_t(\phi)=\zeta_t(A_t\phi)\,\dd t+\dd W_t(\phi)
\end{equation}
is well defined by its backward mild form on a scale of tests with small
Gaussian growth. Its initial field is independent of \(W\), and
\begin{align}
 \E[\zeta_0(\phi)\zeta_0(\psi)]
   &=\int_{\R^6}f_0\phi\psi\,\dd z,\label{eq:initial-covariance}\\
 \E[W_t(\phi)W_s(\psi)]
   &=\int_0^{t\wedge s}C_r(\phi,\psi)\,\dd r.\label{eq:noise-covariance}
\end{align}
The Gaussian noise \(W\) has independent increments. For every integer
\(m\ge1\), fixed times \(t_1,\ldots,t_m\in[0,T]\), and real tests
\(\phi_1,\ldots,\phi_m\in C_c^\infty(\R^6)\),
\begin{equation}\label{eq:main-convergence}
 \bigl(\zeta_{t_1}^\eps(\phi_1),\ldots,
       \zeta_{t_m}^\eps(\phi_m)\bigr)
 \quad\Longrightarrow\quad
 \bigl(\zeta_{t_1}(\phi_1),\ldots,
       \zeta_{t_m}(\phi_m)\bigr)
 \qquad(\eps\downarrow0).
\end{equation}
\end{theorem}

\begin{proposition}[Initial ensemble]\label{prop:initial}
For all sufficiently small $\eps$, the following assertions hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The factorial densities satisfy
\begin{equation}\label{eq:initial-factorial-upper}
 0\le F_{h,0}^{\eps}\le\prod_{j=1}^h f_0(z_j),
 \qquad (1-C\eps)f_0\le g_0\le f_0.
\end{equation}
Consequently $\|g_0-f_0\|_{\Bol,2\beta}=O(\eps)$ and, for every
fixed integer $p\ge1$,
\begin{equation}\label{eq:initial-N-moments}
 \E(N)_p\le\mu^p,
 \qquad \sup_{0<\eps\le\eps_0}\E(N/\mu)^p<\infty.
\end{equation}
\item With $\upsilon=1/81$, for every $h\ge2$,
\begin{equation}\label{eq:initial-coarse-links}
 |c_{h,0}^{\eps}(Z_h)|
 \le (Ch)^{Ch}\prod_{j=1}^h f_0(z_j)
   \sum_{\mathcal T\text{ tree on }[h]}
     \prod_{\{i,j\}\in\mathcal T}
       \bigl(\ind_{|x_i-x_j|\le\eps}+\eps^\upsilon\bigr).
\end{equation}
Here $C$ and the upper bound on $\eps$ are independent of $h$.
For fixed $h\ge2$ and $D>0$ there is $C_{D,h}<\infty$ such that
\begin{equation}\label{eq:initial-sharp-links}
 |c_{h,0}^{\eps}(Z_h)|
 \le C_{D,h}\prod_{j=1}^h f_0(z_j)
   \sum_{\mathcal T\text{ tree on }[h]}
     \prod_{\{i,j\}\in\mathcal T}
       \bigl(\ind_{|x_i-x_j|\le C_{D,h}\eps}+\eps^D\bigr).
\end{equation}
Moreover,
\begin{equation}\label{eq:initial-integrated-cumulants}
 \|c_{h,0}^{\eps}\|_{L^1}\le C_h\eps^{3(h-1)}
 \qquad(h\ge2).
\end{equation}
\item For every finite list of bounded real tests, the exact-centered
initial fluctuations converge jointly to a centered Gaussian vector
with covariance $\int f_0\phi\psi$.
For a smooth compactly supported real test $\phi$, one also has
\begin{equation}\label{eq:initial-centering-shift}
 \lim_{\eps\to0}\sqrt\mu
 \left(\E\pi_0^\eps(\phi)-\int f_0\phi\right)
 =-\frac{4\pi}{3}\int_{\R^6}
       f_0(x,v)\phi(x,v)\varrho_0(x)\,\dd x\,\dd v.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{lemma}[Global weighted integrability]\label{lem:target-moments}
For every $0<q<2\beta$,
\begin{equation}\label{eq:target-velocity-moments}
 \sup_{0\le t\le T}\int_{\R^6}
       f_t(x,v)e^{q|v|^2}\,\dd x\,\dd v<\infty.
\end{equation}
\end{lemma}

\begin{lemma}[Backward evolution]\label{lem:target-propagator}
For $0\le a<b<2\beta$ and $0\le r\le t\le T$, there is a bounded
backward propagator $U(r,t):E_a^0\to E_b^0$.  It solves
\begin{equation}\label{eq:target-backward-mild}
 U(r,t)h=\mathsf S_{t-r}h
   +\int_r^t\mathsf S_{s-r}K_sU(s,t)h\,\dd s,
\end{equation}
has the composition law with intermediate exponents, and is the
unique mild propagator in these scales.  For $\phi\in C_c^\infty$,
\begin{equation}\label{eq:target-upper-end-identity}
 U(r,t)\phi-\phi=\int_r^t U(r,s)A_s\phi\,\dd s.
\end{equation}
\end{lemma}

\begin{proposition}[Gaussian target]\label{prop:gaussian-target}
The fluctuation equation in \Cref{thm:main} has a centered Gaussian
solution on the test scales $E_a^0$, $0\le a<\beta$.  It is a
continuous linear map from each such test space to $L^2$ of its
probability space, uniformly on $[0,T]$.  Its covariance is
\begin{equation}\label{eq:target-covariance}
 \begin{split}
 \E[\zeta_t(\phi)\zeta_s(\psi)]
 ={}&\int f_0(z)\,U(0,t)\phi(z)\,U(0,s)\psi(z)\,\dd z\\
 &+\int_0^{\min(s,t)}
     C_r\bigl(U(r,t)\phi,U(r,s)\psi\bigr)\,\dd r.
 \end{split}
\end{equation}
It is unique in the class of solutions extending to these scales
with uniformly bounded second-moment operator norms.  In particular,
the law required in \Cref{thm:main} is well defined.
\end{proposition}

\begin{lemma}[Kinetic envelopes]\label{lem:kinetic-envelopes}
Under \Cref{ass:kinetic},
\begin{equation}\label{eq:kinetic-bol-propagated}
 \sup_{0\le t\le T}
 \bigl(\|f_t\|_{\Bol,\beta}
       +\|\nabla_x f_t\|_{\Bol,\beta}\bigr)<\infty.
\end{equation}
\end{lemma}

\begin{lemma}[Autonomous partition]\label{lem:autonomous-partition}
For a finite set $V$,
\begin{equation}\label{eq:autonomous-partition}
 \sum_{\mathcal C\in\mathcal P(V)}
 \prod_{C\in\mathcal C}\kappa_C
 \prod_{\{C,D\}\subseteq\mathcal C}\chi(C,D)=1.
\end{equation}
Here $\mathcal P(V)$ denotes the partitions of $V$.  If $S\subseteq V$ is a
root set and $H$ tests the root histories, then
\begin{equation}\label{eq:autonomous-observation}
 H(\Psi_V|_S)=
 \sum_{\mathcal C\in\mathcal P(V)}
 \prod_{C\in\mathcal C}\kappa_C
 \prod_{\{C,D\}\subseteq\mathcal C}\chi(C,D)
 H(\Psi_{\mathcal C}|_S),
\end{equation}
where $\Psi_{\mathcal C}$ is the juxtaposition of the autonomous histories.
\end{lemma}

\begin{lemma}[Rooted forest stopping]\label{lem:rooted-forest}
Let $W$ be a finite vertex set, let $R\subseteq W$ be nonempty, and attach
$a_e\in\{0,1\}$ to each unordered pair of vertices.  Fix $M\ge2$ and set
\begin{equation}\label{eq:ursell-block}
 u(B)=\sum_{\substack{G\text{ connected}\\V(G)=B}}
             \prod_{e\in E(G)}(-a_e),\qquad u(\{w\})=1.
\end{equation}
There is a finite signed remainder $\mathcal R$ such that
\begin{align}\label{eq:finite-rooted-identity}
 \prod_{e\subseteq W}(1-a_e)
 &=\sum_{I:\,R\subseteq I\subseteq W}
   \sum_{\substack{\mathcal B\in\mathcal P(I)\\
               B\cap R\ne\varnothing,\ |B|<M\ (B\in\mathcal B)}}
       \prod_{B\in\mathcal B}u(B)
       \prod_{e\subseteq W\setminus I}(1-a_e)+\mathcal R.
\end{align}
Its absolute value is bounded by a sum of rooted forests.  Each forest in
this bound has exactly one component with $M\le |B|\le2M-2$; its other
components have fewer than $M$ vertices.  All these components meet $R$.
Vertices outside the forest retain their full mutual compatibility
product.  The coefficient of each selected forest in this domination is
at most one.  Moreover,
\begin{equation}\label{eq:ursell-tree-bound}
 |u(B)|\le\sum_{T\text{ spanning tree on }B}\prod_{e\in E(T)}a_e.
\end{equation}
\end{lemma}

\begin{lemma}[One-slab identity and variation remainder]
\label{lem:one-slab-expansion}
For a positive input point-process law, let $F'$ be its factorial
hierarchy after the truncated slab.  If its factorial measures up to the
order in \eqref{eq:stopped-input-order} are finite, then
\begin{equation}\label{eq:one-slab-exact}
 F'_s=\mathcal L_sF+R_s,\qquad |R_s|\le\mathcal E_sF.
\end{equation}
The same statements hold with prescribed records on root labels.
The positive expression $\mathcal E_sF$ is a domination of $R_s$, not an
assertion that the signed remainder has this local kernel.
\end{lemma}

\begin{lemma}[Modified one-root bridge]\label{lem:one-root-bridge}
The difference between $\mathcal U_i(g)$ and the signed unrestricted
one-root particle-tree sum with $n<\Lambda_i/3$ is dominated, after
replacing inputs by $|g|$, by the following positive history integrals:
\begin{enumerate}[label=(\roman*)]
 \item retained one-root molecules with $r\ge1$;
 \item retained one-root molecules with $n\ge\Lambda_i/3$;
 \item the small unrestricted trees with one additional incoming O
 contact inserted between a pair of their flight segments.
\end{enumerate}
The first two families are subsets of the DHM one-root graph class.
The third is its additional-overlap error class.  Coefficients in these
dominations have at most a fixed power of the cutoffs.  The leading
tree coefficient is exactly $(-1)^{\#\mathrm O}$, with the labelled
factorial just stated.
\end{lemma}

\begin{proposition}[Independent factors]\label{prop:one-root}
The measures $g_i$ have Gaussian Bol-bounded density representatives.
With the exponents $\beta_i,\theta_i$ of
\Cref{thm:dhm-package}, for sufficiently small $\eps$,
\begin{equation}\label{eq:one-root-convergence}
 \|g_i-f_{i\tau}\|_{\Bol,\beta_i}\le\eps^{\theta_i},\qquad
 \sup_{0\le i\le L}\|g_i\|_{\Bol,\beta_i}\le C.
\end{equation}
The same estimates hold for the one-root map run through any portion
$\sigma\in[0,\tau]$ of slab $i$, with target
$f_{(i-1)\tau+\sigma}$ and exponent $\beta_i$.
\end{proposition}

\begin{lemma}[Resummation with specified records]
\label{lem:marked-regrouping}
The retained hierarchy admits an exact finite expansion
\begin{equation}\label{eq:dependent-subsets}
 \widehat F^R_{i,S}
   =\sum_{H:\,R\subseteq H\subseteq S}
        E^R_{i,H}\otimes g_i^{\otimes(S\setminus H)}.
\end{equation}
The coefficients can be represented by layered diagrams with the
following rule.  Every retained block in slab $i$ contains a root from
the interface above it.  A block is retained in $E^R_{i,H}$ if it
contains at least two such roots, or it meets a dependent input label
from the interface below.  All other blocks sum to the independent
factor $g_i$ on their unique root.  Every record-bearing line continues
to time zero.  Forgetting any record commutes with
\eqref{eq:retained-hierarchy}; at the diagram level it is effected by
resumming the newly unmarked one-root histories.
\end{lemma}

\begin{lemma}[Labels and connected components]\label{lem:diagram-labels}
The retained expansion factors over its global components.  If
$D^R_{i,B}$ is the sum of its diagrams connected on the designated roots
$B$, then
\begin{equation}\label{eq:component-exponential-formula}
 \widehat F^R_{i,S}
       =\sum_{\pi\in\mathcal P(S)}
                         \bigotimes_{B\in\pi}D^{R\cap B}_{i,B}.
\end{equation}
Consequently factorial-cumulant inversion of the retained hierarchy
keeps exactly its connected diagrams.  This assertion is unchanged by
the resummations into $g_i$.

At fixed root order $h=|S|$ and bounded DHM complexity $\rho\le K$,
let $n_i$ denote the number of
particle lines in slab $i$, and $j_i$ its fresh input labels.  The
labelled denominator is $\prod_i j_i!$, where
\begin{equation}\label{eq:bounded-crossing-factorials}
 n_i-j_i=O_{K,h,m,L}(1),\qquad
 \prod_i\frac1{j_i!}
      \le\frac{(1+\sum_i n_i)^{C_{K,h,m,L}}}{\prod_i n_i!}.
\end{equation}
Apart from the choices of ordinary contact pairs and their order, all
distinguished-label, gluing, initial-block, and record-placement
multiplicities are bounded by a fixed polynomial in total size times
$C^b$, where $b$ is the atom count and the exponential base $C$ does not
depend on $K$ or the moment order.  In the coarse regime the same
choices cost a power of the cutoffs with exponent $O(\rho)$, in addition
to the exponential atom factor.
\end{lemma}

\begin{lemma}[Stopped variation errors]\label{lem:stopped-variation}
Choose $L$ sufficiently large in terms of the fixed data and $\Gamma$.
For any fixed bound on the number of recorded labels, there are
$c_i>0$ such that
\begin{equation}\label{eq:retained-variation-error}
 \|F^R_{i,S}-\widehat F^R_{i,S}\|_{\TV}
                  \le e^{-c_i\Lambda_i},
 \qquad |S|\le A_i/2.
\end{equation}
The constants may decrease with $i$ and the fixed record bound.
The statement is uniform for a partial final slab.  No velocity weight
is claimed for this error.
\end{lemma}

\begin{proposition}[Accuracy of the pasted dynamics]\label{prop:cutoff}
There is a sufficiently large dimensional integer \(\Gamma_0\) with the
following property.  Fix \(\Gamma\geq\Gamma_0\).  There is
\(L_0=L_0(\Gamma,f_0,f,T,\beta)\) such that, for any fixed \(L\geq L_0\),
the true dynamics and the pasted dynamics of
\Cref{thm:marked-expansion}, coupled using the same initial configuration,
satisfy
\begin{equation}\label{eq:cutoff-probability}
 \P\{\text{the two trajectories differ at some time in }[0,T]\}
 \leq C\eps^{1+\eta}
\end{equation}
for all sufficiently small \(\eps\), where one may take
\(\eta=1/20\).  Here the size cutoffs are the \(A_i,\Lambda_i\) of
\Cref{thm:dhm-package}, and \(C\) and the upper bound on \(\eps\) may
depend on the displayed fixed parameters.
\end{proposition}

\begin{lemma}[Removal of very high birth energy]\label{lem:cutoff-energy-tail}
For the positive graph majorants in
\eqref{eq:cutoff-low-complexity}, there is a fixed power \(H_*\)
such that restricting the total birth energy
\(P=\sum_{j\text{ a birth}}|v_j|^2\) to
\[
 P\leq P_{\eps}:=(1+|\log\eps|)^{H_*}
\]
changes their sum by \(O(\eps^M)\) for every fixed \(M\).
\end{lemma}

\begin{lemma}[Local adjacent-pair estimates]\label{lem:cutoff-pair}
Consider every possible choice $e_1,e_2$ of the two prospective fixed
edges of a type-A pair, with $t_1,t_2$ the corresponding contact times.
Call that choice strongly close if
\begin{equation}\label{eq:cutoff-close}
 |t_2-t_1|\leq\eps^{9/10},\qquad
 |v_{e_2}-v_{e_1}|\leq\eps^{4/5}.
\end{equation}
Then:
\begin{enumerate}[label=\textup{(\roman*)}]
\item a primitive pair satisfying \eqref{eq:cutoff-close}, cut
freely as one piece, has mass at most
\begin{equation}\label{eq:cutoff-free-pair}
 C R^C\mu\eps^{9/10+3(4/5)}
 =C R^C\eps^{13/10};
\end{equation}
\item in the absence of every strongly close primitive pair, each
type-A pair used by a cutting sequence has conditional mass at most
\(C R^C\eps^{1/20}\), or may be split into a neutral type-two
piece and a singleton with this same improved bound.
\end{enumerate}
The conditional bounds are uniform in the previously exposed lines
and times.
\end{lemma}

\begin{lemma}[Summation with finitely many exceptional pieces]\label{lem:cutoff-sum}
Consider the positive low-complexity graph integrals obtained
above.  Suppose a cut sequence has \(q=b-O_K(1)\) ordinary
atoms and boundedly many exceptional pieces, whose conditional
mass bounds have product
\(\eps^\alpha|\log\eps|^{C_*}\).
After summing spatial cells and energy bins in a polylogarithmic
energy region, its integral is at most
\begin{equation}\label{eq:cutoff-sum}
 \eps^\alpha|\log\eps|^{C_*}
       (C\tau\sqrt L)^q .
\end{equation}
The exponential base \(C\) depends on the fixed kinetic
envelopes and dimension, but not on \(K,L\).
\end{lemma}

\begin{lemma}[The fresh-label factorials]\label{lem:sharp-factorials}
For diagrams of complexity at most \(K\), the absolute sum with slab
sizes \((n_1,\ldots,n_L)\) is bounded by a sum over chronologically
ordered merger pair lists with denominator \(\prod_i n_i!\), multiplied
by
\begin{equation}\label{eq:sharp-polynomial-count}
 C_K(1+n)^{d_K}C^{\sum_i a_i},
 \qquad n=\sum_i n_i,
\end{equation}
where the base \(C\) does not depend on \(K\).  The merger pairs
themselves are not counted in \eqref{eq:sharp-polynomial-count}.
\end{lemma}

\begin{lemma}[Uniform summability]\label{lem:sharp-summability}
For fixed \(K\), the sum of the absolute connected diagram measures
with slab sizes \((n_i)\), after removal of the factor
\(\mu^{1-h}\), is bounded by
\begin{equation}\label{eq:sharp-summable}
       C_K(1+n)^{d_K}(C\tau\sqrt L)^n.
\end{equation}
The same bound, with the appropriate factor \(\mu^{c-h}\), holds
after a bounded number of initial links are erased.  It also holds
after prescribing the absolute spatial position of one observation
in each component, or after inserting a sufficiently small Gaussian
weight in the designated velocities.
\end{lemma}

\begin{proposition}[Evolution of the marked tree laws]
\label{prop:tree-evolution}
Between observation updates the limiting measures satisfy
\begin{align}
 \partial_tF_t(\Phi)
  &=F_t(D\Phi)+\frac12\int BF_tF_{t,*}\Delta\Phi,
       \label{eq:limit-F-evolution}\\
 \partial_tJ_t(\Phi\otimes\Psi)
  &=J_t\bigl((D+H_t)\Phi\otimes\Psi
                     +\Phi\otimes(D+H_t)\Psi\bigr)\notag\\
  &\quad+\int BF_tF_{t,*}
          \bigl(\Phi(\xi')\Psi(\xi_*')
                         -\Phi(\xi)\Psi(\xi_*)\bigr).
       \label{eq:limit-J-evolution}
\end{align}
The identities hold in transport mild form, and hence in weak
differential form for smooth tests for which the displayed integrals
exist.  At an update \(t_j\),
\begin{equation}\label{eq:limit-pushforwards}
       F_{t_j+}=(\Theta_j)_\#F_{t_j-},
       \qquad
       J_{t_j+}=(\Theta_j\otimes\Theta_j)_\#J_{t_j-}.
\end{equation}
\end{proposition}

\begin{lemma}[History at a filled half-line]\label{bc:halfline-table}
A finite guarded table has a full-domain inverse and simulates the original
machine from a tape with a separately constant tail in each direction.
At checkpoint $n$ its nonempty history cells are exactly the absolute
indices below $2+n$.
\end{lemma}

\begin{proposition}[Mean-corrected vertical transport]\label{bc:halfline-transport}
The preceding full rectangles at height $z_*$ have an effective mean-zero
solenoidal realization on the unit torus. Every tracked first coordinate
is between its endpoint values throughout the transition.
\end{proposition}

\begin{proposition}[A move-first material test]\label{thm:bb-torus33}
The move-first recorder has a unit-torus realization, periodic after
$t=1$, whose fixed label $(1/4,1/2,1/4)$ enters
$\{x_1\in(1/2,1)\pmod1\}$ exactly when the work machine halts.
For a fixed machine only the loading interval depends on the input.
\end{proposition}

\begin{theorem}[A height test inside one torus chart]\label{bc:expanded-height-event}
On the unit torus, the fixed label $o=(1/2,1/2,1/2)$ and event
\begin{equation}\label{bc:expanded-height-fixed-event}
 \{x:x_3\pmod1\in(1/2,1)\}
\end{equation}
realize halting by a smooth general mean-zero force, periodic after time
one, with zero initial velocity and pressure and bounded mixed derivatives.
The repeated mechanism depends on the machine alone; only initialization
depends on its finite input. The solution is unique in the torus class.
\end{theorem}

\begin{theorem}[A half-space test by fixed columns]\label{bc:column-event}
On $\R^3$, the frontier recorder with odd digits in base $2m+1$ realizes
halting from the fixed label $0$ by the event $x_1<-1$. It gives a compactly
supported general force, periodic after time one, with zero initial
velocity and pressure and all mixed derivatives bounded.
\end{theorem}

