\begin{lemma}[Transverse averaging and axial slices]
\label{ker:geometric-slice}
Let $\lambda$ be a probability mixture of the measures
$\mathcal U_d$, $d>0$, and $\delta_0$, and let $\rho$ be any axial
probability measure. No bound on its density or its support is
required. Put $c=\lambda\otimes\rho$. For $R\geq1$, $\bar v\ne0$,
and an interval $I\subset\R$ of length $0<\ell\leq2R$, one has
\begin{align}
 &\frac{1}{W(v)}\int c(\dd p)
   \int_{|\xi-v|\leq R}
    \delta\bigl((v-p)\cdot(\xi-v)\bigr)W(\xi)\,\dd\xi
     \leq C_q R^2,\label{ker:geometric-total}\\
 &\frac{1}{W(v)}\int c(\dd p)
   \int_{\substack{|\xi-v|\leq R\\ \xi_3\in I}}
    \delta\bigl((v-p)\cdot(\xi-v)\bigr)W(\xi)\,\dd\xi
     \leq C_q\bigl(R\ell+R^{q-1}\ell^{2-q}\bigr).
     \label{ker:geometric-interval}
\end{align}
The constants are independent of all transverse widths and of $\rho$.
In particular, these statements hold with $\lambda=\mathcal G_d$ for
every $d\geq0$.
\end{lemma}

\begin{definition}[Uniform sheet class]\label{ker:sheet-class}
Fix $L\geq1$. An elementary sheet in $\mathcal S_L$ is a product
probability measure
\begin{equation}\label{ker:sheet-definition}
 c(\dd p)=\mathcal G_d(\dd\bar p)\rho(\dd p_3),\qquad
 0\leq d\leq\tfrac18,\qquad
 \int_{\R}e^{8a^2}\rho(\dd a)\leq L.
\end{equation}
We also allow probability mixtures of elementary sheets. An upper
bound by a sheet with amplitude $A_0$ means domination as measures by
$A_0$ times such a mixture.
\end{definition}

\begin{lemma}[Uniform sheet gain bound]\label{lem:sheet-bound}
For every $L<\infty$ there is $C_{q,m,L}<\infty$ such that
\begin{equation}\label{ker:sheet-gain}
 P(c,H)(v)\leq C_{q,m,L}H(v)
 \quad\hbox{for almost every }v,
 \qquad c\in\mathcal S_L.
\end{equation}
More quantitatively, for $R\geq1$,
\begin{equation}\label{ker:shell-tail}
 \mathcal K_c\bigl(v;
      R<|p|+|\xi-v|\leq2R\bigr)
 \leq C_{q,m,L}R^2e^{-cR^2},
\end{equation}
where $c>0$ is an absolute constant. The same conclusions, multiplied
by $A_0$, hold under sheet domination with amplitude $A_0$.
\end{lemma}

\begin{lemma}[Uniform tightness and axis estimates]
\label{lem:kernel-tightness}
Fix $L<\infty$. The following conclusions hold uniformly for
$c\in\mathcal S_L$ and for outgoing velocities off the axis.
\begin{enumerate}[label=\textup{(\roman*)}]
\item The tails in $|p|+|\xi-v|$ are uniformly negligible:
\begin{equation}\label{ker:uniform-tail}
 \lim_{R\to\infty}\sup_{c\in\mathcal S_L}\esssup_v
 \mathcal K_c(v;|p|+|\xi-v|>R)=0.
\end{equation}
Also,
\begin{equation}\label{ker:large-output}
 \lim_{M\to\infty}\sup_{c\in\mathcal S_L}
 \esssup_{|v|>M}\mathcal K_c(v;\R^3\times\R^3)=0.
\end{equation}
\item For every fixed $M,\delta>0$,
\begin{align}
 &\lim_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L}
 \esssup_{\substack{|v|\leq M\\0<|\bar v|\leq\varepsilon}}
 \mathcal K_c(v;|\bar\xi|\geq\delta)=0,
 \label{ker:axis-input}\\
 &\lim_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L}
 \esssup_{\substack{|v|\leq M\\0<|\bar v|\leq\varepsilon}}
 \mathcal K_c(v;|v_3-p_3|\geq\delta)=0.
 \label{ker:axis-mismatch}
\end{align}
\item The axial input marginals are uniformly non-atomic. More
precisely, for each $R\geq1$ and each interval $I$ of length
$0<\ell\leq1$,
\begin{equation}\label{ker:axial-interval}
 \mathcal K_c(v;|p|+|\xi-v|\leq R,\ \xi_3\in I)
 \leq C_{q,m,L,R}\bigl(\ell+\ell^{2-q}\bigr).
\end{equation}
In combination with \eqref{ker:uniform-tail}, this gives
\begin{equation}\label{ker:axial-modulus}
 \lim_{\ell\downarrow0}\sup_{c\in\mathcal S_L}\esssup_v
 \sup_{|I|\leq\ell}\mathcal K_c(v;\xi_3\in I)=0.
\end{equation}
\item Let $\mathcal S_L(\varepsilon)$ denote the subclass whose
elementary transverse widths are at most $\varepsilon$. For every
$M<\infty$ and $r_0>0$,
\begin{equation}\label{ker:off-axis-small-input}
 \lim_{\delta\downarrow0}\limsup_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L(\varepsilon)}
 \esssup_{\substack{|v|\leq M\\|\bar v|\geq r_0}}
 \mathcal K_c(v;|\bar\xi|<\delta)=0.
\end{equation}
\end{enumerate}
All these conclusions hold under uniformly bounded sheet amplitudes.
\end{lemma}

\begin{lemma}[Quadratic gain bound]\label{lem:hot-bound}
There is a constant $C_{q,m}$ such that
\begin{equation}\label{ker:hot-gain}
 P(H,H)\leq C_{q,m}H
 \quad\hbox{almost everywhere}.
\end{equation}
In fact the proof below works for every $m>5$.
\end{lemma}

\begin{lemma}[Barrier identities]
\label{jet:barrier}
The constant \(C_m\) can be chosen so that \(f_i\le m_i\) on
\([0,\overline T]\), uniformly in the label.  Moreover, almost
everywhere along every free characteristic,
\begin{equation}
 \D m_i\ge
 \left(1+\tfrac78 |w_i|^2/d_{s_j}^2\right)m_i .
 \label{jet:barrier-derivative}
\end{equation}
There is a constant \(C_\nu\), independent of the label, such that
\begin{equation}
 P(m_i,m_i)=m_i\nu_{m_i},\qquad
 \nu_{m_i}(v)\le C_\nu\frac K{s_j}(d_{s_j}+|w_i|).
 \label{jet:barrier-collision}
\end{equation}
Every free core remains in its own spatial enlargement:
\[
 f_i(t,x,v)>0\quad\Longrightarrow\quad x\in\mathcal O_i(t).
\]
\end{lemma}

\begin{proposition}[Uniform cold control]
\label{prop:cold-control}
There is a constant \(L\), depending on the fixed parameters, such
that after imposing the additional condition
\begin{equation}
 Ld_0\overline s^9\le1,
 \label{jet:thermal-comparison}
\end{equation}
the following statements hold at every time of existence of the
finite approximation in \(0\le t\le\overline T\).
\begin{enumerate}[label=\textup{(\roman*)}]
 \item For every retained label \(i=(j,\sigma,n)\),
 \begin{equation}
  0\le c_i\le f_i+\varepsilon_j m_i,\qquad
  \varepsilon_j=Ld_{s_j}/s_j .
  \label{jet:cold-remainder}
 \end{equation}
 \item At each spatial point call the unique label with
 \(x\in\mathcal O_i(t)\), if one exists and is retained, the main
 label.  Let \(c_{\mathrm{main}}\) be that color, or zero, and set
 \(e=c-c_{\mathrm{main}}\).  For every \(A\ge0\),
 \begin{equation}
  0\le e(t,x,v)\le C_A t^A e^{-4|v|^2}.
  \label{jet:escaped}
 \end{equation}
 The upper bound remains valid after restricting the escaped sum
 to any subset of its labels.
 \item If the main label has scale \(s\), its velocity measure is
 bounded by a fixed multiple of \((t+s)^{-1}\) times a sum of
 admissible probability sheets from Lemma~\ref{lem:sheet-bound}.
 Its free-core contribution has the exact parameterization
 \eqref{eq:core-jacobian} below.  The remainder has the smaller
 velocity-mass coefficient \(Cd_s/s^2\).
 In particular, for every fixed \(k\ge0\),
 \begin{equation}
  \int_{\R^3}\langle v\rangle^k c_{\mathrm{main}}\,\dd v
       \le\frac{C_k}{t+s},\qquad
  \int_{|v|>R}\langle v\rangle^k c_{\mathrm{main}}\,\dd v
       \le\frac{C_k e^{-c_kR^2}}{t+s}\quad(R\ge3).
  \label{jet:moment-envelope}
 \end{equation}
 \item For the mixed-cold source in the hot equation,
 \begin{equation}
  \sum_{\substack{i,j\in\mathcal I_N\\i\ne j}}
       P^b(c_i,c_j)(t,x,v)
       \le C_A t^{A-1}H(v)\qquad (t>0)
  \label{jet:mixed-source}
 \end{equation}
 for every \(A\ge0\), with constants uniform in \(N\) and \(b\).
\end{enumerate}
\end{proposition}

\begin{corollary}[Survival of a cold core under the cap]
\label{jet:survival}
Suppose a finite approximation satisfies
\[
 0\le h(t,x,v)\le(t+s_N)H(v)
\]
on an initial interval \([0,T]\subset[0,\overline T]\).
All conclusions below concern times \(t\in[0,T]\).
For every \(M\ge0\) there are constants \(C,C_M\), independent of
\(T,N\), the cutoff, and the seed, such that
\begin{equation}
\begin{gathered}
 e^{-E_{s,N}(t)}f_i(t,x,v)
       \le c_i(t,x,v)
       \le f_i(t,x,v)+L(d_s/s)m_i(t,x,v),\\
 E_{s,N}(t)=C(d_st/s+t^2+s_Nt)+C_Mt^{M+1}
\end{gathered}
 \label{jet:survival-sandwich}
\end{equation}
for every label of scale \(s\).
Consequently, if \(r\to0\), \(s_N\le r\), \(s/r\in[\epsilon,R]\)
for fixed \(0<\epsilon<R<\infty\), and \(0\le t\le\min(T,Ar)\), then
\[
 E_{s,N}(t)\le
 C_{\epsilon,R,A}(d_s+r^2)+C_{M,A}r^{M+1}\longrightarrow0
\]
uniformly in the label and in points of its free core.
The transverse free displacement divided by the stripe period
satisfies
\begin{equation}
 \frac{td_s}{s^2}\le
       C_{\epsilon,R,A}r^9\longrightarrow0.
 \label{jet:stripe-displacement}
\end{equation}
On these scales the difference between cold and free-core
velocity measures also satisfies, uniformly in position and time,
\begin{equation}
 r\int_{\R^3}|c_i-f_i|(t,x,v)\,\dd v\longrightarrow0.
 \label{jet:survival-measure}
\end{equation}
\end{corollary}

\begin{proposition}\label{prop:finite-cap}
There is a fixed \(T_0>0\) such that the following statements hold.
\begin{enumerate}[label=\textup{(\alph*)}]
\item With \(\lambda=0\), the finite approximations exist on \([0,T_0]\)
and satisfy \(0\le h\le t^2H\).
\item There is a fixed finite \(L_0\) such that, for every
\(0<T\le T_0\) and every \(N\), some \(\lambda\in[0,L_0]\) gives an
approximation on \([0,T]\) with
\begin{equation}\label{eq:cap}
0\le h(t,x,v)\le(t+s_N)H(v),\qquad
\max_{0\le t\le T}\frac{\|h(t)\|_H}{t+s_N}=1.
\end{equation}
\end{enumerate}
In both cases all cold components obey Proposition~\ref{prop:cold-control}.
\end{proposition}

\begin{lemma}[Characteristic matching and small scales]
\label{nc:characteristic-matching}
On every compact set with \(t\ge a>0\), the following statements
hold uniformly.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If \(a\le t_2\le t_1\), \(\Delta=t_1-t_2\), and
\(z_2=z_1-\Delta w\), then
\begin{equation}
\label{nc:matching-inequality}
 |w-u_{\mu,\sigma}(t_1,z_1)|
 \le |w-u_{\mu,\sigma}(t_2,z_2)|.
\end{equation}
\item As \(\mu\downarrow0\), the distance of
\(u_{\mu,\sigma}(t,z)\) to
\[
 \{z/t,\ \sigma-\alpha,\ \sigma+\alpha\}
\]
tends to zero uniformly.  For the perturbed axial velocity in
\eqref{nc:core-parameters},
\begin{equation}
\label{nc:thermal-speed-error}
 |p_3-u_{\mu,\sigma}(t,z)|\le d_s|w_3|.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}[Redundant plane parameters]
\label{nc:plane-parameters}
Let \(n\ne0\), \(e=n/|n|\), and let \(\zeta\) be a bounded
nonnegative function supported in \([-1,1]\) with integral one.
For every nonnegative measurable \(F\),
\begin{equation}
\label{nc:plane-identity}
 \int_{n^\perp} F(k)\frac{\dd A(k)}{|n|}
 =
 \int_{\R^3}F(n\times L)|n|\zeta(L\cdot e)\dd L .
\end{equation}
If \(\delta\le|n|\le R\) and \(|k|\le R_1\), the right side is
supported in
\[
 |L|\le\sqrt{(R_1/\delta)^2+1}
\]
and has density at most \(R\|\zeta\|_\infty\).
The identity can be applied successively when each normal is a
measurable function of parameters chosen at earlier gains.
\end{lemma}

\begin{lemma}[Uniform pullback estimate]
\label{nc:uniform-pullback}
Let \(\mathcal O\subset\R^k\) be open, \(k\ge d\), and suppose
\(\Phi_n,\Phi:\mathcal O\to\R^d\) satisfy
\(\Phi_n\to\Phi\) in \(C^1_{\mathrm{loc}}\) and
\(\operatorname{rank}D\Phi=d\) almost everywhere.
Let \(K\Subset\mathcal O\) and \(B\subset\R^d\) be compact.
Let \(a_n\) be measurable, supported in \(K\), with
\(|a_n|\le A\).  Let \(F_n\) be measurable, supported in \(B\),
with \(|F_n|\le M\), and converging to zero in measure.  Then
\begin{equation}
\label{nc:pullback-conclusion}
 \int_{\mathcal O}|F_n(\Phi_n(q))a_n(q)|\dd q\longrightarrow0 .
\end{equation}
No convergence or continuity of the densities \(a_n\) is required.
\end{lemma}

\begin{lemma}\label{br:minorization}
There are \(r_0>0\) and \(\varepsilon_0>0\) such that
\begin{equation}\label{br:doeblin}
P_1(v,A)\ge\varepsilon_0|A\cap B(0,r_0)|\quad(v\in E)
\end{equation}
for every Borel set \(A\subset E\). For each \(\zeta>0\), there is also
\(\varepsilon_\zeta>0\) such that
\[
P_1(v,B(e_1,\zeta)\cap\{|v'|<D\})\ge\varepsilon_\zeta\quad(v\in E).
\]
\end{lemma}

\begin{lemma}\label{br:reference-block}
There is a finite \(L\) such that, for all
\[
A\in I_L:=\left[\frac L{1+d},\frac L{1-d}\right],\qquad v\in E,
\]
reference branching histories with velocities in \(E\), final velocity
strictly inside \(E\), and displacement \(Z_A\) satisfying
\begin{equation}\label{br:strict-drift}
|Z_A-\kappa Ae_1|<\frac34d\kappa A
\end{equation}
have total weight greater than 8.
\end{lemma}

\begin{lemma}\label{br:robust-block}
For these fixed \(\kappa,L\), there are \(J\in\N\) and
\(\varepsilon_*\in(0,1/4)\) with the following property. Suppose a
measurable medium obeys, throughout every speed-\(D\) excursion from
a specified starting point over a duration \(A\in I_L\),
\begin{equation}\label{br:medium-closeness}
|b_\sigma-1|\le\varepsilon_*,
\qquad |w_\sigma-\sigma e_3|\le\varepsilon_*
\quad(\sigma=\pm1).
\end{equation}
From each starting velocity in \(E\), histories with at most \(J\)
collisions, speed at most \(D\) on every free flight, every
postcollision velocity and the final velocity strictly inside \(E\), and
\begin{equation}\label{br:robust-drift}
|Z_A-\kappa Ae_1|<d\kappa A
\end{equation}
have total weight greater than 3. The initial free flight may have
speed \(D\). No continuity of the medium is needed.
\end{lemma}

\begin{lemma}[Transverse averaging and axial slices]
\label{ker:geometric-slice}
Let $\lambda$ be a probability mixture of the measures
$\mathcal U_d$, $d>0$, and $\delta_0$, and let $\rho$ be any axial
probability measure. No bound on its density or its support is
required. Put $c=\lambda\otimes\rho$. For $R\geq1$, $\bar v\ne0$,
and an interval $I\subset\R$ of length $0<\ell\leq2R$, one has
\begin{align}
 &\frac{1}{W(v)}\int c(\dd p)
   \int_{|\xi-v|\leq R}
    \delta\bigl((v-p)\cdot(\xi-v)\bigr)W(\xi)\,\dd\xi
     \leq C_q R^2,\label{ker:geometric-total}\\
 &\frac{1}{W(v)}\int c(\dd p)
   \int_{\substack{|\xi-v|\leq R\\ \xi_3\in I}}
    \delta\bigl((v-p)\cdot(\xi-v)\bigr)W(\xi)\,\dd\xi
     \leq C_q\bigl(R\ell+R^{q-1}\ell^{2-q}\bigr).
     \label{ker:geometric-interval}
\end{align}
The constants are independent of all transverse widths and of $\rho$.
In particular, these statements hold with $\lambda=\mathcal G_d$ for
every $d\geq0$.
\end{lemma}

\begin{definition}[Uniform sheet class]\label{ker:sheet-class}
Fix $L\geq1$. An elementary sheet in $\mathcal S_L$ is a product
probability measure
\begin{equation}\label{ker:sheet-definition}
 c(\dd p)=\mathcal G_d(\dd\bar p)\rho(\dd p_3),\qquad
 0\leq d\leq\tfrac18,\qquad
 \int_{\R}e^{8a^2}\rho(\dd a)\leq L.
\end{equation}
We also allow probability mixtures of elementary sheets. An upper
bound by a sheet with amplitude $A_0$ means domination as measures by
$A_0$ times such a mixture.
\end{definition}

\begin{lemma}[Uniform sheet gain bound]\label{lem:sheet-bound}
For every $L<\infty$ there is $C_{q,m,L}<\infty$ such that
\begin{equation}\label{ker:sheet-gain}
 P(c,H)(v)\leq C_{q,m,L}H(v)
 \quad\hbox{for almost every }v,
 \qquad c\in\mathcal S_L.
\end{equation}
More quantitatively, for $R\geq1$,
\begin{equation}\label{ker:shell-tail}
 \mathcal K_c\bigl(v;
      R<|p|+|\xi-v|\leq2R\bigr)
 \leq C_{q,m,L}R^2e^{-cR^2},
\end{equation}
where $c>0$ is an absolute constant. The same conclusions, multiplied
by $A_0$, hold under sheet domination with amplitude $A_0$.
\end{lemma}

\begin{lemma}[Uniform tightness and large-output decay]
\label{lem:kernel-tightness}
Fix $1\leq L<\infty$. Uniformly for $c\in\mathcal S_L$ and outgoing
velocities off the axis, the tails in $|p|+|\xi-v|$ are negligible:
\begin{equation}\label{ker:uniform-tail}
 \lim_{R\to\infty}\sup_{c\in\mathcal S_L}\esssup_v
 \mathcal K_c(v;|p|+|\xi-v|>R)=0.
\end{equation}
Moreover,
\begin{equation}\label{ker:large-output}
 \lim_{M\to\infty}\sup_{c\in\mathcal S_L}
 \esssup_{|v|>M}\mathcal K_c(v;\R^3\times\R^3)=0.
\end{equation}
Both conclusions hold under uniformly bounded sheet amplitudes.
\end{lemma}

\begin{lemma}[Quadratic gain bound]\label{lem:hot-bound}
There is a constant $C_{q,m}$ such that
\begin{equation}\label{ker:hot-gain}
 P(H,H)\leq C_{q,m}H
 \quad\hbox{almost everywhere}.
\end{equation}
In fact the proof below works for every $m>5$.
\end{lemma}

\begin{lemma}[Gain estimate from small mass]
\label{lem:gain-small-mass}
For each $0\leq B<\infty$ and $\varepsilon>0$ there is a finite
constant $C_{B,\varepsilon}$ such that every measurable density $j$
with $0\leq j\leq BH$ satisfies
\begin{equation}\label{ker:gain-small-mass}
 P(H,j)(v)\leq H(v)
 \left(\varepsilon+C_{B,\varepsilon}
                         \int_{\R^3}j(p)\,\dd p\right)
 \qquad\hbox{for almost every }v.
\end{equation}
The same constant works with $P^b$ in place of $P$.
\end{lemma}

\begin{lemma}[Separation from the axis]\label{con:lattice}
There is a numerical constant \(c>0\) such that
\begin{equation}
 |\bar n|\ge\frac{c}{1+|n|}\qquad
             (n\in\Lambda\setminus\{0\}).
 \label{con:diophantine}
\end{equation}
\end{lemma}

\begin{lemma}[Barrier estimates]\label{cold:barrier}
A fixed sufficiently large \(C_m\) gives, for \(0\le t\le L_s\),
\begin{align}
 f_i&\le m_i,\qquad
 \D m_i\ge \frac1{L_s}
       \left(1+\frac78\frac{|\xi|^2}{d_s^2}\right)m_i,
 \label{cold:barrier-derivative}\\
 P(m_i,m_i)&=m_i\nu_{m_i}
       \le C\frac K{s}(d_s+|\xi|)m_i.
 \label{cold:barrier-gain}
\end{align}
The differential inequality holds almost everywhere along flights.
For sufficiently small \(s_0\),
\(f_i(t,x,v)>0\) implies \(x\in\mathcal O_i(t)\) throughout the
same time interval.
\end{lemma}

\begin{proposition}[Control of every active color]\label{cold:control}
There is a fixed constant \(C_*\) such that, with
\[
 \epsilon_s=C_*L_sd_s/s,\qquad
 \mathcal U_i=f_i+\epsilon_s m_i,
\]
and sufficiently small \(s_0\), every finite colored evolution obeys
\begin{equation}
 0\le c_i(t,x,v)\le\mathcal U_i(t,x,v)\qquad (0\le t\le L_{s_i})
 \label{cold:upper}
\end{equation}
as long as that color is active and the solution exists.
If, on an interval beginning at \(t_1\), one also has
\(\nu_F^b\ge\kappa>0\), then
\begin{equation}
 c_i(t,x,v)\le e^{-\kappa(t-t_1)}\mathcal U_i(t,x,v)\qquad
                   (t_1\le t\le L_{s_i})
 \label{cold:decay}
\end{equation}
throughout that interval.  None of the constants in
\eqref{cold:upper} uses a bound on the bath or hot density.
\end{proposition}

\begin{lemma}[Core formula and sheet amplitudes]\label{cold:core-amplitude}
At a fixed \((t,x)\), the velocity measure \(f_i(t,x,p)\dd p\) is the
pushforward of
\begin{equation}
 \frac{K S(\gamma(z_c-tp_3)/s)}
          {s+t\alpha\gamma S(\gamma(z_c-tp_3)/s)}\,J(w)\dd w,\qquad
 \bar p=d_s\bar w,\quad
 p_3=a_s^\sigma(z_c-tp_3)+d_sw_3,
 \label{cold:core-formula}
\end{equation}
with the initial spatial masks evaluated at \(x-tp\).
For \(t\le L_s\), it is dominated by probability sheets with total
amplitude \(C/(t+s)\).  The remainder
\(\epsilon_s m_i\dd p\) has sheet amplitude at most
\begin{equation}
 C L_sd_s/s^2\le Cs^{15/2}\le C/(t+s).
 \label{cold:remainder-amplitude}
\end{equation}
Thus the full upper bound \(\mathcal U_i\dd p\) has sheet amplitude \(C/(t+s)\).
In particular, for every fixed \(k\ge0\), a main color satisfies
\begin{equation}
 \int\langle p\rangle^k c_i(t,x,p)\dd p\le\frac{C_k}{t+s},\qquad
 \int_{|p|>R}\langle p\rangle^k c_i(t,x,p)\dd p
       \le\frac{C_k e^{-c_kR^2}}{t+s}\quad(R\ge3).
 \label{cold:moments}
\end{equation}
\end{lemma}

\begin{lemma}[Nonmain tails]\label{cold:nonmain}
There is a function \(\theta_0(s_0)\to0\) as \(s_0\downarrow0\)
such that, uniformly at all times of existence,
\begin{equation}
 \sum_{\substack{i\ \mathrm{active}\\x\notin\mathcal O_i(t)}}
       \mathcal U_i(t,x,v)
       \le\theta_0(s_0)e^{-4|v|^2}.
 \label{cold:nonmain-bound}
\end{equation}
For \(0<t\le1\), and any fixed \(A,B>0\), the coefficient can instead
be taken to be \(C_{A,B}t^A s_0^B\).  Both assertions remain valid
for an arbitrary subset of the active labels.
\end{lemma}

\begin{lemma}[Size at retirement and volume of active tubes]
\label{cold:retirement-size}
For some fixed constants \(C,C'>0\),
\begin{equation}
 \left\|\sum_{i:\,s_i=s}\mathcal U_i(L_s)\right\|_H
       \le C s^{-C'}.
 \label{cold:retirement-bound}
\end{equation}
Moreover, uniformly over the active label sets and all times,
\begin{equation}
 |\mathcal O(t)|\le\sum_{j\ge1}C s_j^2(1+L_{s_j})
                    \le C s_0^{3/2}.
 \label{cold:tube-volume}
\end{equation}
\end{lemma}

\begin{lemma}[Bath barrier]\label{early:bath}
There are $t_1\in(0,1/32]$, $\beta'>4$, and constants $C,c>0$,
independent of $\delta$, $R_\mu$, and $s_0$, such that every finite evolution
of \eqref{con:colors} satisfies, on its interval of existence,
\begin{equation}\label{early:bath-bound}
 0\le u(t,x,v)\le C e^{-\beta'|v|^2}
       \exp\!\left(-\frac{cD_0(x)^2}{t}\right),
 \qquad 0<t\le t_1,
 \qquad D_0(x)=\dist(x,D_{\rm hole}^c).
\end{equation}
For sufficiently small $s_0$ depending on $\delta$, one also has
\begin{equation}\label{early:hole-distance}
 D_0(x)\ge\delta
 \qquad (0\le t\le t_1,\ x\in\mathcal O(t)).
\end{equation}
\end{lemma}

\begin{lemma}[Source estimates]\label{early:source-estimates}
For sufficiently small $s_0$ depending on $\delta$, every finite evolution
satisfies
\begin{equation}\label{early:source}
 P(c+u,H)\le\frac{C}{t+s_N}H,
 \qquad
 0\le\mathcal S\le C_{A,\delta}t^{A-1}H,
 \qquad 0<t\le t_1,
\end{equation}
on its interval of existence, for every fixed $A>0$.
Here $C$ is independent of $\delta$ and $R_\mu$, and the constants are
uniform for all sufficiently small $s_0$. No bound on $h$ is assumed.
\end{lemma}

\begin{proposition}[Cap selection]\label{early:cap-selection}
For fixed $\delta>0$, there are $\bar s_0,T_0>0$, uniform in $N$ and
the collision cutoff, with the following property.
For each $0<s_0\le\bar s_0$, each $0<T\le T_0$, and each finite
approximation, a seed parameter
$\lambda\in(0,L_0)$ gives a solution on $[0,T]$ satisfying
\begin{equation}\label{early:cap}
 Z(t)\le m_T(t+s_N)\quad(0\le t\le T),
 \qquad
 \max_{0\le t\le T}\frac{Z(t)}{m_T(t+s_N)}=1.
\end{equation}
The dormant solution exists on a fixed initial interval and satisfies
\begin{equation}\label{early:dormant-bound}
 Z(t)\le C'_{A,\delta}t^A.
\end{equation}
The interval and constant in \eqref{early:dormant-bound} are independent
of $N$, the collision cutoff, and sufficiently small $s_0$.
\end{proposition}

\begin{lemma}[Small source along free paths]\label{early:path-source}
Fix $0<t_b<t_1$. There is a function $E_{t_b}(s_0)$ tending to zero as
$s_0\to0$ such that, for every finite evolution and every terminal time
$t\in[t_b,t_1]$ in its interval of existence,
\begin{equation}\label{early:source-integral}
 \left\|\int_{t_b}^t
    \mathcal S(s,x-(t-s)v,v)\dd s\right\|_H
 \le E_{t_b}(s_0).
\end{equation}
This estimate is uniform in the hot seed, the cap horizon, the
approximation index, and the collision cutoff.
\end{lemma}

\begin{lemma}[Averaging along free flights]\label{global:flight-average}
Let $A:[0,\infty)\times(\R^3/\Lambda)\to[0,\infty)$ be measurable,
write $A_s=A(s,\cdot)$, and suppose
\[
 \sup_s\|A_s\|_\infty\le A_*,\qquad
 \sup_s\|A_s\|_1\le a_*.
\]
For a fixed bounded velocity set $V$ and $\rho>0$,
\begin{equation}\label{global:ball-average}
 \int_V A_s(x-\tau v)\dd v
 \le C_{V,\rho}a_*
 \qquad(\tau\ge\rho),
\end{equation}
uniformly in $x,s,\tau$.  If $A_*$ is fixed, the following quantities
tend to zero as $a_*\to0$:
\begin{align}
 &\sup_{t\ge t_1,x}
 \int_{t_1}^t e^{-\kappa(t-s)}
       \int H(v)A_s(x-(t-s)v)\dd v\dd s,
       \label{global:damped-average}\\
 &\sup_{t\ge t_1,x}
 \int_0^{t_1}\int H(v)A_s(x-(t-s)v)\dd v\dd s,
       \label{global:early-average}
\end{align}
where $\kappa>0$ and $t_1>0$ are fixed.  The supremum in $x$ is essential.
\end{lemma}

\begin{lemma}[A collision frequency independent of the bootstrap size]
\label{global:frequency}
There is a constant $\kappa>0$, depending only on the fixed Maxwellian
$\mu$ and $t_1$, with the following property.  For each fixed $B>B_0+2$,
if $\varepsilon_E$ is sufficiently small depending on $B$, then every
finite evolution satisfying \eqref{global:bootstrap} obeys
\begin{equation}\label{global:frequency-bound}
 \nu_F^b(t,x,v)\ge\kappa\qquad(t\ge t_1).
\end{equation}
The constant is uniform for $b\ge1$ and for all approximation indices.
\end{lemma}

\begin{lemma}[Uniform nonlinear gain]\label{global:gain}
Let $B>B_0+2$ be fixed and suppose \eqref{global:bootstrap} holds on an
interval beginning at $t_1$.  After taking
$\varepsilon_E$, $\zeta$, and $s_0$ sufficiently small depending on $B$,
one has on that interval
\begin{equation}\label{global:gain-bound}
 P^b(w,w)\le C_5H,
 \qquad C_5:=\|P(\mu,\mu)\|_H+1.
\end{equation}
In particular, $C_5$ is independent of $B$, the approximation, and the
cap horizon.  The estimate holds also at the appropriate one-sided
sections of retirement times.
\end{lemma}

\begin{lemma}[Kernel estimates near the axis]
\label{lem:axis-kernel-estimates}
Fix $1\leq L<\infty$. The following conclusions hold uniformly for
$c\in\mathcal S_L$ and for outgoing velocities off the axis.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For every fixed $M,\delta>0$,
\begin{align}
 &\lim_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L}
 \esssup_{\substack{|v|\leq M\\0<|\bar v|\leq\varepsilon}}
 \mathcal K_c(v;|\bar\xi|\geq\delta)=0,
 \label{ker:axis-input}\\
 &\lim_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L}
 \esssup_{\substack{|v|\leq M\\0<|\bar v|\leq\varepsilon}}
 \mathcal K_c(v;|v_3-p_3|\geq\delta)=0.
 \label{ker:axis-mismatch}
\end{align}
\item The axial input marginals are uniformly non-atomic. More
precisely, for each $R\geq1$ and each interval $I$ of length
$0<\ell\leq1$,
\begin{equation}\label{ker:axial-interval}
 \mathcal K_c(v;|p|+|\xi-v|\leq R,\ \xi_3\in I)
 \leq C_{q,m,L,R}\bigl(\ell+\ell^{2-q}\bigr).
\end{equation}
In combination with \eqref{ker:uniform-tail}, this gives
\begin{equation}\label{ker:axial-modulus}
 \lim_{\ell\downarrow0}\sup_{c\in\mathcal S_L}\esssup_v
 \sup_{|I|\leq\ell}\mathcal K_c(v;\xi_3\in I)=0.
\end{equation}
\item Let $\mathcal S_L(\varepsilon)$ denote the subclass whose
elementary transverse widths are at most $\varepsilon$. For every
$M<\infty$ and $r_0>0$,
\begin{equation}\label{ker:off-axis-small-input}
 \lim_{\delta\downarrow0}\limsup_{\varepsilon\downarrow0}
 \sup_{c\in\mathcal S_L(\varepsilon)}
 \esssup_{\substack{|v|\leq M\\|\bar v|\geq r_0}}
 \mathcal K_c(v;|\bar\xi|<\delta)=0.
\end{equation}
\end{enumerate}
All these conclusions hold under uniformly bounded sheet amplitudes.
\end{lemma}

\begin{lemma}[Characteristic matching and small scales]
\label{nc:characteristic-matching}
On every compact set with \(t\ge a>0\), the following statements
hold uniformly.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If \(a\le t_2\le t_1\), \(\Delta=t_1-t_2\), and
\(z_2=z_1-\Delta w\), then
\begin{equation}
\label{nc:matching-inequality}
 |w-u_{\varrho,\sigma}(t_1,z_1)|
 \le |w-u_{\varrho,\sigma}(t_2,z_2)|.
\end{equation}
\item As \(\varrho\downarrow0\), the distance of
\(u_{\varrho,\sigma}(t,z)\) to
\[
 \{z/t,\ \sigma-\alpha,\ \sigma+\alpha\}
\]
tends to zero uniformly.  For the perturbed axial velocity in
\eqref{nc:core-parameters},
\begin{equation}
\label{nc:thermal-speed-error}
 |p_3-u_{\varrho,\sigma}(t,z)|\le d_s|w_3|.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}[Redundant plane parameters]
\label{nc:plane-parameters}
Let \(n\ne0\), \(e=n/|n|\), and let \(\zeta\) be a bounded
nonnegative function supported in \([-1,1]\) with integral one.
For every nonnegative measurable \(F\),
\begin{equation}
\label{nc:plane-identity}
 \int_{n^\perp} F(k)\frac{\dd A(k)}{|n|}
 =
 \int_{\R^3}F(n\times L)|n|\zeta(L\cdot e)\dd L .
\end{equation}
When \(\delta\le|n|\le R\) and the plane integral is restricted
to \(|k|\le R_1\), the corresponding parameter measure
\(\ind_{\{|n\times L|\le R_1\}}|n|\zeta(L\cdot e)\dd L\)
is supported in
\[
 |L|\le\sqrt{(R_1/\delta)^2+1}
\]
and has density at most \(R\|\zeta\|_\infty\). This bound concerns
the parameter measure before multiplication by \(F(n\times L)\).
The identity can be applied successively when each normal is a
measurable function of parameters chosen at earlier gains.
\end{lemma}

\begin{lemma}[Uniform pullback estimate]
\label{nc:uniform-pullback}
Let \(\mathcal O\subset\R^k\) be open, \(k\ge d\), and suppose
\(\Phi_n,\Phi:\mathcal O\to\R^d\) satisfy
\(\Phi_n\to\Phi\) in \(C^1_{\mathrm{loc}}\) and
\(\operatorname{rank}D\Phi=d\) almost everywhere.
Let \(K\Subset\mathcal O\) and \(B\subset\R^d\) be compact.
Let \(a_n\) be measurable, supported in \(K\), with
\(|a_n|\le A\).  Let \(F_n\) be measurable, supported in \(B\),
with \(|F_n|\le M\), and converging to zero in measure.  Then
\begin{equation}
\label{nc:pullback-conclusion}
 \int_{\mathcal O}|F_n(\Phi_n(q))a_n(q)|\dd q\longrightarrow0 .
\end{equation}
No convergence or continuity of the densities \(a_n\) is required.
\end{lemma}

\begin{lemma}\label{br:minorization}
There are \(r_0>0\) and \(\varepsilon_0>0\) such that
\begin{equation}\label{br:doeblin}
P_1(v,A)\ge\varepsilon_0|A\cap B(0,r_0)|\quad(v\in E)
\end{equation}
for every Borel set \(A\subset E\). For each \(\zeta>0\), there is also
\(\varepsilon_\zeta>0\) such that
\[
P_1(v,B(e_1,\zeta)\cap\{|v'|<D\})\ge\varepsilon_\zeta\quad(v\in E).
\]
\end{lemma}

\begin{lemma}\label{br:reference-block}
There is a finite \(L\) such that, for all
\[
A\in I_L:=\left[\frac L{1+d},\frac L{1-d}\right],\qquad v\in E,
\]
reference branching histories with velocities in \(E\), final velocity
strictly inside \(E\), and displacement \(Z_A\) satisfying
\begin{equation}\label{br:strict-drift}
|Z_A-\varkappa Ae_1|<\frac34d\varkappa A
\end{equation}
have total weight greater than 8.
\end{lemma}

\begin{lemma}\label{br:robust-block}
For these fixed \(\varkappa,L\), there are \(J_{\mathrm{br}}\in\N\) and
\(\varepsilon_*\in(0,1/4)\) with the following property. Suppose a
measurable medium obeys, throughout every speed-\(D\) excursion from
a specified starting point over a duration \(A\in I_L\),
\begin{equation}\label{br:medium-closeness}
|b_\sigma-1|\le\varepsilon_*,
\qquad |w_\sigma-\sigma e_3|\le\varepsilon_*
\quad(\sigma=\pm1).
\end{equation}
From each starting velocity in \(E\), histories with between \(1\) and
\(J_{\mathrm{br}}\) collisions, speed at most \(D\) on every free flight, every
postcollision velocity and the final velocity strictly inside \(E\), and
\begin{equation}\label{br:robust-drift}
|Z_A-\varkappa Ae_1|<d\varkappa A
\end{equation}
have total weight greater than 3. The initial free flight may have
speed \(D\). No continuity of the medium is needed.
\end{lemma}

\begin{lemma}[Growth in the limiting medium]\label{br:block-growth}
For the parameters just fixed, let \(a_{\rm br}=L\varkappa/(\theta K)\).
There is a time \(t_{\mathrm{br}}>0\), independent of the mesh and
\(l\in[0,1]\), such that every density satisfying the equation, cap,
and mild formula of Proposition~\ref{prop:finite-dilated-horizon} on
an interval containing \([t,(1+a_{\rm br})t]\), with \(t\ge t_{\mathrm{br}}\),
obeys, at its positive-time traces,
\begin{equation}\label{br:mass-growth}
 M((1+a_{\rm br})t)\ge3M(t),\qquad
 M(s):=\int_{\mathcal B_s}g(s,x,v)\dd x\dd v.
\end{equation}
\end{lemma}

\begin{lemma}[Onto changes of clock]\label{bcs:clock}
Fix $\nu>0$. Let $W(s,x)$ be a smooth divergence-free field for $s\ge0$, on a flat torus or on $\mathbb R^3$. Suppose all its mixed derivatives are bounded, $W(0)=0$, and in the whole-space case its spatial support lies in a fixed compact set. Let $g:[0,\infty)\to[0,\infty)$ be smooth, nondecreasing, onto, with $g(0)=0$. Then
\begin{align}
 u(t,x)&=g'(t)W(g(t),x),\\
 f(t,x)&=g''(t)W(g(t),x)-\nu g'(t)\Delta W(g(t),x)\notag\\
 &\quad +(g'(t))^2[\partial_sW+(W\cdot\nabla)W](g(t),x)
 \label{bcs:clock-force}
\end{align}
gives a prescribed solution with pressure zero and zero initial velocity. Its material flow is $X_u(t,a)=X_W(g(t),a)$, and hence preserves every all-time reachability event. If $(W\cdot\nabla)W=0$ identically, $f$ is divergence free. Spatial mean zero, when imposed on $W$, is inherited by $u$ and $f$.

For $g(t)=\log(1+t)$, every $j\ge0$ and spatial multi-index $\alpha$ satisfy
\begin{equation}\label{bcs:log-bounds}
 \|\partial_t^jD_x^\alpha u(t)\|_\infty+
 \|\partial_t^jD_x^\alpha f(t)\|_\infty
 \le C_{j,\alpha}(1+t)^{-1-j}.
\end{equation}
All these derivatives belong to $L^2([0,\infty);L^\infty)$; on a torus or with fixed compact support they also belong to space-time $L^2$.
\end{lemma}

\begin{lemma}\label{bcs:expanded-compiler}
The initialized table reaches a stop state exactly when the ordinary partial-table machine halts. Otherwise it has defined transitions forever. On its full allowed domain, the destination state and full written symbol determine a unique incoming rule; the destination alone determines its displacement.
\end{lemma}

\begin{lemma}\label{bcs:expanded-processor}
There is an effective smooth planar Hamiltonian field $V(s,Y)$, period one in $s$ and zero near each integer phase, with support in $(1/8,7/8)^2$ and spatial mean zero, whose period map equals $T_i$ on each full $R_i$. All mixed derivatives have effective uniform bounds. A rectangle with a non-stop destination stays in $1/8<Y_1<3/8$ throughout its transition. The trajectory from $c_L$ enters $2/3<Y_1<5/6$ exactly when the machine halts, and a halting visit occurs at an integer phase.
\end{lemma}

\begin{proposition}\label{bcs:expanded-material}
For each fixed computable $\nu>0$, the machine and input effectively determine a smooth period-one mean-zero force on $\mathbb T^3$, all of whose derivatives are bounded, such that the solution from zero velocity has its particle from $X_*$ enter $\mathcal S$ exactly when the machine halts. A separate choice of force is stationary for $t\ge1$, also with bounded derivatives and the same fixed event. Both constructions have pressure zero. The stationary choice has a generally nonzero mean force during startup.
\end{proposition}

\begin{theorem}\label{bcs:prefix-theorem}
For fixed computable $\nu>0$, every deterministic one-tape machine and finite input effectively determine a smooth mean-zero force on the unit torus, with zero initial velocity, such that
\[
 \|\partial_t^jD_x^\alpha f(t)\|_\infty\le C_{j,\alpha}(1+t)^{-1-j}
\]
for every $j,\alpha$. The unique global smooth velocity satisfies the same bounds. Its particle from $(1/4,1/2,1/2)$ enters $\{1/2<x_1<1\}$ exactly when the machine halts. One choice of force has pressure zero; projecting that force gives a divergence-free choice with the same velocity and a changed normalized pressure. For a fixed machine, the repeated motion before the clock change is independent of the input; only its initial loading motion changes.
\end{theorem}

\begin{lemma}\label{bcs:prefix-symbolic}
The full domain cylinders of these rules are pairwise disjoint, and their full image cylinders are pairwise disjoint. Initialized checkpoints recover the ordinary machine configurations. Each ordinary transition takes a positive finite number of prefix steps, and a terminal checkpoint occurs exactly on halting.
\end{lemma}

\begin{lemma}\label{bcs:prefix-planar}
Let $D_i,E_i$, $1\le i\le m$, be rational axis-aligned closed rectangles of positive side lengths. Suppose the $D_i$ are pairwise disjoint in $\Omega_-=(0,1/2)\times(0,1)$, the $E_i$ are pairwise disjoint in $\Omega=(0,1)^2$, and each $E_i$ lies entirely in one open half of $\Omega$. There is an effective smooth field $v_*(s,Y)$ supported in $(0,1)\times\Omega$ whose time-one map on each full $D_i$ is its positive diagonal affine identification with $E_i$. If $E_i\subset\Omega_-$, the whole trajectory from $D_i$ remains in $\Omega_-$. No incompressibility is asserted in this planar lemma.
\end{lemma}

\begin{lemma}\label{bcs:delayed-recorder}
At successive ready states the auxiliary table has exactly the ordinary work tape, head and state. It reaches an $R_{h,d}$ exactly when the ordinary machine halts. Every ordinary step uses a positive finite number of auxiliary steps. On the full domain of the auxiliary table, a destination state fixes the incoming displacement, and that state together with the full written symbol determines the incoming rule.
\end{lemma}

\begin{corollary}[Failure of universal Gaussian global existence]
\label{cor:gaussian}
For the fixed power $p$ and index $k$ in Theorem~\ref{thm:blowup}, and
for every $\alpha>k+6$, the initial datum
\begin{equation}\label{eq:gaussian}
 u_0^\omega(x)=\sum_{n\in\mathbb Z^{12}}
       g_n(\omega)\langle n\rangle^{-\alpha}e^{in\cdot x}
\end{equation}
belongs to $H^k$ almost surely and has positive probability of finite-time
blowup. In particular, the following assertion is false: for every
energy-supercritical pair $(d,p)$ there is a finite $\alpha_0(d,p)$
such that, for every $\alpha>\alpha_0(d,p)$ and every
\[
 d/2+2<m<\alpha-d/2,
\]
the local $H^m$ solution with the Gaussian datum extends almost surely
to $C(\mathbb R;H^m(\mathbb T^d))$.
\end{corollary}

\begin{lemma}[Regularized slow solution]\label{free:slow}
For $\operatorname{Re}q>-1$, $\operatorname{Re}x\ge0$, $x\ne0$, define, with
principal powers,
\begin{equation}\label{free:H-definition}
 H(q,m,x)=x^{-q}\left\{1+\frac1{\Gamma(q)}
 \int_0^\infty e^{-u}u^{q-1}
 \left[(1+u/x)^{m-1-q}-1\right]\,du\right\}.
\end{equation}
Here $m$ may in particular be any positive integer used below.  This
definition is holomorphic in $q$, including $q=0$, and in $x$ on the
interior of the indicated region, with holomorphic continuation across
each nonzero point of its imaginary boundary.  Primes on $H$ denote
derivatives in its last argument.  It satisfies
\begin{equation}\label{free:H-equation}
 xH''+(m-x)H'-qH=0,\qquad
 H'(q,m,x)=-qH(q+1,m+1,x),\qquad H(0,m,x)=1.
\end{equation}
For every $N\ge1$ it has the expansion
\begin{equation}\label{free:H-expansion}
 H(q,m,x)=x^{-q}\left\{
 \sum_{j=0}^{N-1}\frac{(-1)^j(q)_j(1+q-m)_j}{j!x^j}
 +O(|x|^{-N})\right\}.
\end{equation}
Here $(q)_0=1$ and $(q)_j=\prod_{n=0}^{j-1}(q+n)$ for $j\ge1$.
The expansion is uniform for $\operatorname{Re}x\ge0$, $|x|\ge1$, and compact parameter
sets.  The same remainder estimate holds after any fixed number of
$x\partial_x$ derivatives of the bracket.  The symbol expansion specifies
the slow solution, without an oscillatory component on the imaginary
rays.
\end{lemma}

\begin{lemma}[Laguerre recurrence]\label{free:laguerre}
Let $L_n(t)=e^t\partial_t^n(e^{-t}t^n)/n!$ be the Laguerre polynomials,
orthonormal for $e^{-t}\,dt$ on $[0,\infty)$.  Write
\[
 G=\sum_{n\ge0}g_nL_n,\qquad
 B_n=\sum_{k\ge n}g_k,\qquad C_n=\sum_{k\ge n}(k-n)g_k.
\]
These series and their parameter derivatives converge rapidly.  With
$t_n=q+n$ and $d_n=t_n-M$, one has
\begin{align}
 &(B_0,C_0)=(G(0),-G'(0)),\label{free:initial-tail}\\
 &t_ng_n=-MB_{n+1}-sC_n,\qquad
 d_nB_{n+1}=t_nB_n+sC_n,\qquad
 C_{n+1}=C_n-B_{n+1}.\label{free:recurrence}
\end{align}
The real quadratic form
\begin{equation}\label{free:cone-form}
 p_n=\frac M2|B_n|^2+\operatorname{Re}(s\overline{B_n}C_n)
\end{equation}
satisfies the exact identity
\begin{equation}\label{free:cone-increment}
 p_{n+1}-p_n=
 (\operatorname{Re}\lambda+n-5/2)|g_n|^2.
\end{equation}
\end{lemma}

\begin{lemma}[Strict normalized cone]\label{free:cone}
Suppose $\operatorname{Re}\lambda\ge-1/32$ and $K\ge3$.  For $n\ge K$
the normalized coefficients $\widehat g_n=g_n/(q)_K$, and their sums
$\widehat B_K=B_K/(q)_K$, $\widehat C_K=C_K/(q)_K$, extend
holomorphically across $q=0$.  They satisfy
\begin{equation}\label{free:strict-cone}
 \frac M2|\widehat B_K|^2+
 \operatorname{Re}(s\overline{\widehat B_K}\widehat C_K)
 =-\sum_{n\ge K}(\operatorname{Re}\lambda+n-5/2)
 |\widehat g_n|^2<0.
\end{equation}
Consequently $\widehat C_K\ne0$, and
\begin{equation}\label{free:tail-disk}
 R_h=\widehat B_K/\widehat C_K\quad\hbox{is holomorphic},\qquad
 |R_h+s/M|<Z/M.
\end{equation}
\end{lemma}

\begin{lemma}[Analytic matching columns]\label{free:columns}
Define
\begin{equation}\label{free:backward}
 F_n=\begin{pmatrix}d_n-s&-s\\t_n&t_n\end{pmatrix},\qquad
 P_K=F_0F_1\cdots F_{K-1}.
\end{equation}
Then, including parameters where an individual $t_n$ or $d_n$ vanishes,
\begin{equation}\label{free:column-identity}
 P_K\begin{pmatrix}R_h\\1\end{pmatrix}
 =\frac1{\widehat C_K}
 \begin{pmatrix}H(q,M+1,-s)\\-H'(q,M+1,-s)\end{pmatrix}.
\end{equation}
The scalar on the right is holomorphic and nonzero.  The column is
nonzero.
\end{lemma}

\begin{lemma}\label{free:high-angular}
For $(b,Z)\in\mathcal D$, $\ell\ge4$, and
$\operatorname{Re}\lambda\ge-1/32$, one has $\Delta_\ell(\lambda;b,Z)\ne0$.
\end{lemma}

\begin{lemma}[Winding count]\label{free:winding}
For $0\le\ell\le3$ the zero counts in Proposition~\ref{free:main} are
$2,1,0,0$, respectively.
\end{lemma}

\begin{lemma}[Profile matching degree]\label{free:profile-degree}
The first conclusion of Proposition~\ref{free:main} holds.  More
precisely there is an invertible real-linear map
$\mathcal L:\mathbb R^2\to\mathbb C$ with negative determinant and
minimum stretch greater than $.048$ such that
\begin{equation}\label{free:profile-linearization}
 |j(b,Z)-\mathcal L(b-b_*,Z-Z_*)|<2.5\cdot10^{-11}
 \qquad((b,Z)\in\mathcal D).
\end{equation}
In particular $|j|>4.55\cdot10^{-10}$ on $\partial\mathcal D$.
\end{lemma}

\begin{lemma}[Exterior inequalities]\label{free:exterior}
For $(b,Z)\in\mathcal D$, $H(-ib,6,-iz)$ is nonzero for all $z\ge Z$,
and the inequalities in \eqref{free:exterior-bounds} and
$\operatorname{Im}j(b,z)>0$ for $z\ge3$ hold.  In radial variables,
for any nonzero constant multiple $Q(r)$ of $H(-ib,6,-ir^2/4)$,
\begin{equation}\label{free:radial-quotients}
 \frac{A'}A=-\frac r2\operatorname{Im}j(b,r^2/4),\qquad
 \frac wr=\frac12+\operatorname{Re}j(b,r^2/4),
 \quad A=|Q|,\quad w=r/2+2\partial_r\arg Q.
\end{equation}
\end{lemma}

\begin{lemma}[Uniform spatial estimates]\label{lin:spatial}
The embeddings $Y\hookrightarrow C_0(\mathbb R^{12})$ and
$Y_L\hookrightarrow L^\infty(\mathbb T_L^{12})$ are bounded, uniformly for
$L\ge1$.  Both spaces are algebras, with a uniform algebra constant for
$Y_L$.  For a ball or annulus of radius $R\ge1$, contained in one torus
cell when appropriate and with $R\le C_0L$, one has
\begin{equation}\label{lin:local-derivatives}
 \|\nabla^jv\|_{L^2(\text{ball or annulus})}
 \le C R^{\max(s_0-j,0)}\|v\|,
 \qquad 0\le j\le k.
\end{equation}
Here and below an undecorated norm denotes the applicable $Y$ or $Y_L$
norm, and constants may depend on the fixed geometric constant $C_0$.

If $F$ satisfies $|\nabla^jF|\le C_j\langle y\rangle^{-\beta-j}$, then
a smooth dyadic piece supported where $|y|\asymp R$ satisfies
\begin{equation}\label{lin:symbol-norm}
 \|\psi_RF\|\le C\big(R^{6-\beta-s_0}+R^{6-\beta-k}\big),
\end{equation}
also on the tori for $R\le C_0L$.  In particular $Q\in Y$, and for every
fixed $\chi\in C_c^\infty(B_1)$ the cutoff profiles $\chi(y/L)Q(y)$
have uniformly bounded $Y_L$ norms.
\end{lemma}

\begin{lemma}[Compact errors]\label{lin:compact-error}
For every $\varepsilon>0$ there are $R_\varepsilon,C_\varepsilon<\infty$
such that
\begin{equation}\label{lin:compact-bound}
 \|\mathcal V_*v\|_{s_0,*}
 +\|\nabla^k(\mathcal V_*v)-\mathcal V_*\nabla^kv\|_2
 \le\varepsilon\|v\|+C_\varepsilon\|v\|_{L^2(B_{R_\varepsilon})}.
\end{equation}
Here $*$ denotes either the whole-space potential and homogeneous
low-order norm, or a torus potential at its current scale and the
regularized low-order norm in \eqref{lin:YL}.  The constants are uniform
for all sufficiently large current torus scales.  The potential acts
componentwise on the ordered tensor in the second term.
\end{lemma}

\begin{proposition}[Energy observation inequality]\label{lin:observation}
There are $c>0$, $C<\infty$, and $R_0<\infty$ such that every whole-space
linear solution, and every torus linear solution with sufficiently large
starting scale, satisfies
\begin{equation}\label{lin:energy-observation}
 \frac{d}{ds}\|v(s)\|^2
 \le-c\|v(s)\|^2+C\|v(s)\|_{L^2(B_{R_0})}^2.
\end{equation}
The derivative can equivalently be understood through the integrated
inequality.  The constants are independent of the torus scale and of
the slab length.  In particular, for $t\ge0$,
\begin{equation}\label{lin:integrated-observation}
 \|v(t)\|^2\le e^{-ct}\|v(0)\|^2
   +C\int_0^t e^{-c(t-s)}\|v(s)\|_{L^2(B_{R_0})}^2\,ds.
\end{equation}
\end{proposition}

\begin{theorem}[Stable whole-space evolution]\label{linear:decay}
There is a bounded real-linear map $\pi:Y\to\mathbb R^{14}$ such that
\begin{equation}\label{lin:spectral-coordinates}
 \pi E=I,\qquad S(s)E=Ee^{s\Lambda},\qquad
 \pi S(s)=e^{s\Lambda}\pi\quad(s\in\mathbb R).
\end{equation}
For some $C_S<\infty$ and $\eta>0$,
\begin{equation}\label{lin:stable-decay}
 \|S(s)v\|_Y\le C_Se^{-\eta s}\|v\|_Y,
 \qquad s\ge0,\quad \pi v=0.
\end{equation}
Thus $E\pi$ is the symmetry spectral projection.  Constants depend on
the fixed profile, $a$, and $k$.
\end{theorem}

\begin{lemma}[Nonlinear step estimate]\label{nl:step}
There are $\delta>0$, $L_0<\infty$ and $C_M<\infty$ such that, for
$L\geq L_0$, the perturbation equation $U=Q_s+v$ has a unique solution
through the step whenever $\|v(0)\|_{Y_L}\leq\delta$. Its endpoint is
\[
 v(M)=\mathcal F_Lv(0)+h_L(v(0)),
\]
where
\begin{align}
 \|h_L(0)\|&\leq C_M L^{-2-a},\label{nl:step-zero}\\
 \operatorname{Lip}_{\|v\|\leq d}h_L
   &\leq C_M(d+L^{-2-a})\qquad(0<d\leq\delta).
 \label{nl:step-lip}
\end{align}
During the step,
\[
 \sup_{0\leq s\leq M}\|v(s)\|_{Y_{L_s}}
 \leq C_M\bigl(\|v(0)\|_{Y_L}+L^{-2-a}\bigr).
\]
\end{lemma}

\begin{proposition}[Profiles and uniform estimates]\label{profile:existence}
There is $a_0>0$ such that, for every $0<a<a_0$, there are
$(b_a,Z_a)\in\mathcal D$ and a smooth nonvanishing radial stationary
solution $Q_a=A_ae^{i\phi_a}$ of \eqref{profile:similarity}, normalized by
$Q_a(0)>0$.  They have the following properties.
\begin{enumerate}
\item The identities \eqref{profile:amplitude}--\eqref{profile:divergence}
hold, $0<P_a\le1$, and there are constants $c,C>0$, independent of small
$a$, such that
\begin{equation}\label{profile:coercive-bounds}
 C^{-1}\langle r\rangle^{-4a}\le\mu_a(r)
       \le C\langle r\rangle^{-4a},\qquad
 \nabla w_a\ge c I.
\end{equation}
\item If $a_n\downarrow0$ and $(b_{a_n},Z_{a_n})\to(b,Z)$, then
$j(b,Z)=0$, where $j$ is the free matching function of
Proposition~\ref{free:main}.  With $R=2\sqrt Z$, the profiles converge in
$C^1$ on every compact ball to
\begin{equation}\label{profile:limit}
 Q_0(r)=
 \begin{cases}
 1,&0\le r\le R,\\[2pt]
 \displaystyle\frac{H(-ib,6,-ir^2/4)}{H(-ib,6,-iZ)},&r\ge R.
 \end{cases}
\end{equation}
The exterior amplitude is strictly decreasing and has a positive limit
at infinity.  The convergence is $C^\infty$ on compact subsets of
$\{r>R\}$.  On every fixed ball,
\begin{equation}\label{profile:pressure-limit}
 P_{a_n}\ \stackrel{*}{\rightharpoonup}\ b\mathbf1_{\{r<R\}}
       \quad\hbox{in }L^\infty,
\end{equation}
and $\mu_{a_n},w_{a_n}$ converge in $C^1$.  In particular
$P_{a_n}/a_n\to0$ locally uniformly on $\{r>R\}$.
\item On the fixed exterior $r\ge r_b$,
\begin{equation}\label{profile:tail}
 Q_a(r)=r^{\nu_a}f_a(r),\qquad \nu_a=-2a+2ib_a,
 \qquad 0<\kappa\le|f_a(r)|\le\rho<1,
\end{equation}
with $\kappa,\rho$ independent of $a$.  There are coefficients
$m_{a,j}$, with $|m_{a,0}|\ge\kappa$, such that for every pair of fixed
nonnegative integers $N,J$,
\begin{equation}\label{profile:symbol-expansion}
 \left|D^j\left(f_a(r)-\sum_{q=0}^{N}m_{a,q}r^{-2q}\right)\right|
       \le C_{N,J}r^{-2N-2},\qquad 0\le j\le J,\quad r\ge r_b.
\end{equation}
The constants are uniform as $a\downarrow0$.  In particular,
\begin{equation}\label{profile:exterior-pressure}
 |D^j(P_a/a)|\le\eta_j(a)r^{-2},\qquad
 |D^je^{2i\phi_a}|\le C_j,\qquad \eta_j(a)\longrightarrow0
\end{equation}
for each fixed $j$.  On the inner ball,
\begin{equation}\label{profile:pressure-transport}
 W_a(P_a/a)\le Ca(P_a/a),\qquad r\le r_b,
\end{equation}
whereas $|W_a(P_a/a)|\le\eta(a)r^{-2}$ for $r\ge r_b$, with
$\eta(a)\to0$.  Consequently the positive part of $W_a(P_a/a)$ is
bounded uniformly on the whole space.
\item For each fixed $a$, every Cartesian derivative obeys
\begin{equation}\label{profile:fixed-power-symbols}
 |\partial^\beta Q_a(y)|\le C_{a,\beta}\langle y\rangle^{-2a-|\beta|},
 \qquad
 \left|\partial^\beta\big((P_a/a)e^{2i\phi_a}\big)\right|
       +|\partial^\beta(P_a/a)|
       \le C_{a,\beta}\langle y\rangle^{-2-|\beta|}.
\end{equation}
The time-symmetry combination has the improved exterior order
\begin{equation}\label{profile:time-symbol}
 \left|D^j\left((a-ib_a+D/2)Q_a\right)\right|
       \le C_j r^{-2a-2},\qquad r\ge r_b.
\end{equation}
\end{enumerate}
\end{proposition}

\begin{lemma}[The boundary modulus]\label{profile:boundary-modulus}
Uniformly on $\mathcal D$,
\begin{equation}\label{profile:boundary-gap}
 1-.2\varepsilon^2<h_b<1-.15\varepsilon^2.
\end{equation}
For fixed $b$ in the projection of $\mathcal D$, the function
$R'\mapsto|F(r_b;b,R')|$ is strictly increasing on $[r_0,r_b)$.
\end{lemma}

\begin{lemma}[The inner amplitude]\label{profile:inner}
For all sufficiently small $a>0$ and all $(b,Z)\in\mathcal D$, the
system \eqref{profile:amplitude} has a positive radial solution on
$[0,r_b]$ with $A'(0)=0$ and $A(r_b)=h_b$.  Within the bounds
\begin{equation}\label{profile:inner-bounds}
 h_b\le A\le .5^a,
\end{equation}
it is unique.  It depends continuously on $(b,Z)$, and obeys
\begin{equation}\label{profile:bulk-barrier}
 A(r)\ge .2^a-.02(r-r_0)_+^2.
\end{equation}
The amplitudes are bounded uniformly in $C^{1,1}[0,r_b]$.
\end{lemma}

\begin{lemma}[The pressure derivative and positive deformation]
\label{profile:pressure}
The matched profiles satisfy \eqref{profile:coercive-bounds} and
\eqref{profile:exterior-pressure}--\eqref{profile:pressure-transport}.
\end{lemma}

\begin{lemma}[Upper bound for the real part]\label{spec:real-bound}
For all sufficiently small $a$, there is no nonzero regular outgoing
mode with $\operatorname{Re}\lambda\ge4$.
\end{lemma}

\begin{lemma}[Outgoing data at the remote endpoint]\label{spec:remote-data}
Every outgoing solution along this sequence satisfies
\begin{equation}\label{spec:remote-robin}
 q_h'(E)-hi\sqrt{F_h(E)}q_h(E)=O(E^{-1})|q(E)|.
\end{equation}
The constant is uniform after discarding finitely many sequence terms.
\end{lemma}

\begin{lemma}[Coupled outgoing data on a fixed shell]\label{spec:boundary-estimate}
After subselection, every outgoing solution along an escaping
parameter sequence satisfies, uniformly on $B_0\le R\le B_1$,
\begin{equation}\label{spec:shell-robin}
 q_h'(R)=\mathcal B_h(R)q_h(R)+o(n_*)|q(R)|.
\end{equation}
The error is an operator bound on the two-dimensional outgoing space.
\end{lemma}

\begin{lemma}[Exclusion of escaping parameters]\label{spec:high-exclusion}
There is no sequence of nonzero regular outgoing modes with $a\to0$,
$-1/32\le\operatorname{Re}\lambda\le4$, and
$\ell+|\operatorname{Im}\lambda|\to\infty$.
\end{lemma}

\begin{lemma}[The analytic compact pencil]\label{spec:compact-pencil}
Near each bounded candidate $\lambda$, choose $B_2$ sufficiently large.
The regular outgoing mode equation is equivalent to
\begin{equation}\label{spec:compact-equation}
 (I-\mathcal C_a(\lambda))z=0\quad\hbox{on }\mathscr Z,\qquad
 \mathcal C_a(\lambda)=j_ET_aK_a(\lambda).
\end{equation}
These are compact holomorphic families, and
$\mathcal C_a\to\mathcal C_0$ locally uniformly in operator norm.
\end{lemma}

\begin{lemma}[Interface conditions and the limiting determinant]
\label{spec:interface}
The limiting kernel in \eqref{spec:compact-equation} consists of free
slow exterior modes satisfying
\begin{equation}\label{spec:matching}
 f(R)=0,\qquad g(R+)=g(R-),\qquad g'(R+)=g'(R-),\qquad
 g(r)=c r^\ell\quad(r<R).
\end{equation}
It is nonzero exactly when the two-column determinant of
Proposition~\ref{free:main} vanishes.
\end{lemma}

\begin{maintheorem}[Regular-lifespan kinetic limit]\label{thm:main}
Let $\Phi$ satisfy Assumption~\ref{pre:potential}, and let $\beta>0$.
Let $f_0\ge0$ be a $C^1$ probability density on $\R^3\times\R^3$ such that
\begin{equation}\label{intro:data-bound}
 \|f_0\|_{\mathrm{Bol},2\beta}
 +\|\nabla_xf_0\|_{\mathrm{Bol},2\beta}<\infty.
\end{equation}
Fix $0<T<\infty$ for which the equation
\begin{equation}\label{intro:boltzmann}
 (\partial_t+v\cdot\nabla_x)f=Q_\Phi(f,f),
 \qquad f|_{t=0}=f_0,
\end{equation}
has a nonnegative classical probability-density solution satisfying
\begin{equation}\label{intro:solution-bound}
 \sup_{0\le t\le T}\sup_{x,v}
 e^{2\beta|v|^2}f(t,x,v)<\infty.
\end{equation}
Start the exact Newtonian process from the grand-canonical law
\eqref{pre:model}. For its scaled factorial densities
$F_s^\varepsilon$, defined in \eqref{pre:factorial}, every fixed
integer $s\ge1$ satisfies
\begin{equation}\label{intro:chaos}
 \lim_{\varepsilon\downarrow0}\;
 \sup_{0\le t\le T}
 \bigl\|F_s^\varepsilon(t)-f(t)^{\otimes s}\bigr\|_
 {L^1((\R^3\times\R^3)^s)}=0.
\end{equation}
\end{maintheorem}

\begin{maincorollary}[Empirical observables]\label{cor:empirical}
Under the hypotheses of Theorem~\ref{thm:main}, let
$a\in C_c^\infty(\R^3\times\R^3;\R)$ and $\eta>0$. Then
\begin{equation}\label{intro:empirical}
 \lim_{\varepsilon\downarrow0}\;
 \sup_{0\le t\le T}
 \PP\!\left(
 \left|\mu_\varepsilon^{-1}\sum_{i=1}^{N}a(z_i(t))
       -\int a(z)f(t,z)\,dz\right|>\eta\right)=0.
\end{equation}
\end{maincorollary}

\begin{assumption}[Potential class]\label{pre:potential}
Write $\Phi(q)=\phi(|q|)$, with $\Phi(q)=0$ for $|q|\geq1$.
Assume either $\Phi\in C^2(\mathbb R^3;\mathbb R)$, or
$\Phi\in C^2(\mathbb R^3\setminus\{0\})$ with
$\Phi(q)\to+\infty$ as $q\to0$.
In the latter case set $\Phi(0)=+\infty$.
Assume thermodynamic stability: for some $B\geq0$,
\begin{equation}\label{eq:pre-stability}
 \sum_{\substack{i,j\in R\\i<j}}\Phi(q_i-q_j)\geq-B|R|
\end{equation}
for every finite configuration of distinct points.
The potential is fixed independently of $\varepsilon$.
\end{assumption}

\begin{proposition}[Initial insertion and centering]\label{pre:initial}
Put $\rho_0(x)=\int f_0(x,v)\,dv$, and assume $\|\rho_0\|_\infty<\infty$.
At time zero,
\begin{equation}\label{eq:pre-insertion}
 \begin{split}
 \widetilde F_R^\varepsilon(0,Z_R)
 &=F_R^\varepsilon(0,Z_R)\\
 &=f_0^{\otimes R}(Z_R)\mathbf1_{{\cal D}_R^\varepsilon}(Z_R)
       \mathbb E\prod_{i\in R}\mathbf1_{\{N(B_i)=0\}},
 \qquad B_i=\overline B(x_i,\varepsilon).
 \end{split}
\end{equation}
The expectation is over an independent cloud with the original law,
and $N(B)$ counts its positions in $B$.
Consequently $0\leq F_R^\varepsilon(0)\leq f_0^{\otimes R}$.

For $Z_R\in{\cal D}_R^\varepsilon$, define
\begin{equation}\label{eq:pre-initialcenter}
 E_R^\varepsilon(0,Z_R)=
 \sum_{S\subset R}(-1)^{|R\setminus S|}
      f_0^{\otimes(R\setminus S)}(Z_{R\setminus S})
      \widetilde F_S^\varepsilon(0,Z_S).
\end{equation}
There are $c_0>0,C_0<\infty$, independent of $R,\varepsilon$, such that
for sufficiently small $\varepsilon$,
\begin{equation}\label{eq:pre-centersmall}
 |E_R^\varepsilon(0,Z_R)|
       \leq(C_0\varepsilon^{c_0})^{|R|}f_0^{\otimes R}(Z_R).
\end{equation}
One may take $c_0=1/125$.
For fixed $r$,
\begin{equation}\label{eq:pre-mass}
 0\leq1-\int F_R^\varepsilon(0,Z_R)\,dZ_R
       \leq Cr\varepsilon+Cr^2\varepsilon^3,
 \qquad \int F_R^\varepsilon(t)=\int F_R^\varepsilon(0).
\end{equation}
\end{proposition}

\begin{lemma}[Residence-time flux]\label{pre:duration}
For every $M<\infty$ there is $C_M<\infty$ such that
\begin{equation}\label{eq:pre-duration}
 \int_{\substack{|g|\leq M\\n\in S^2,\ n\cdot g<0}}
 \tau_*(n,g)|n\cdot g|\,d\sigma(n)\,dg\leq C_M.
\end{equation}
The incoming flux of $\{\tau_*>D,\ |g|\leq M\}$ is at most $C_M/D$.
In particular $\tau_*<\infty$ almost everywhere in incoming flux.
The entrance-to-exit scattering map preserves flux.
\end{lemma}

\begin{definition}[The scattering collision operator]
Write $c=(v+v_*)/2$, $g=v-v_*$, and, for almost every incoming datum,
let $g_{\rm out}$ be the velocity after exit. Set
\[
 v'=c+\tfrac12g_{\rm out},\qquad
 v_*'=c-\tfrac12g_{\rm out}.
\]
For $\psi\in C_c^\infty(\mathbb R^3)$, define $Q_\Phi$ at each $x$ by
\begin{equation}\label{pre:collision}
 \begin{split}
 \int Q_\Phi(f,f)(x,v)\psi(v)\,dv
 =\frac12\int_{\mathbb R^3\times\mathbb R^3}
 & f(x,v)f(x,v_*)|v-v_*|\\
 {}\times\int_{\substack{b\in(v-v_*)^\perp\\|b|<1}}
 &[\,\psi(v')+\psi(v_*')-\psi(v)-\psi(v_*)\,]\,
                         d^2b\,dv\,dv_* .
 \end{split}
\end{equation}
Here $d^2b$ is Euclidean area, and the $g=0$ contribution is zero.
Null exceptional scattering data are ignored.
\end{definition}

\begin{lemma}[Reversibility and normalization]\label{pre:operator}
The measure $d\Lambda=|v-v_*|\,dv\,dv_*\,d^2b$ is preserved by
exchanging incoming and outgoing velocity pairs with the corresponding
entrance parameter. The weak definition \eqref{pre:collision} equals
\begin{equation}\label{eq:pre-Qstrong}
 Q_\Phi(f,f)(x,v)=
 \int_{\mathbb R^3}|v-v_*|
 \int_{\substack{b\in(v-v_*)^\perp\\|b|<1}}
 [\,f(x,v')f(x,v_*')-f(x,v)f(x,v_*)\,]\,d^2b\,dv_* .
\end{equation}
These identities hold whenever the integrals are absolutely convergent,
in particular for Gaussian bounded functions. All scattering branches
are included, and the impact disk has area $\pi$.
\end{lemma}

\begin{proposition}[Known-solution envelopes]\label{pre:envelopes}
Suppose $f$ is the classical nonnegative solution in the statement, and
\[
 A=\sup_{0\leq t\leq T}\|f(t)\|_{\infty,2\beta}<\infty,\qquad
 B_0=\|f_0\|_{\mathrm{Bol},2\beta}
               +\|\nabla_xf_0\|_{\mathrm{Bol},2\beta}<\infty.
\]
Then
\begin{equation}\label{eq:pre-envelope}
 \sup_{0\leq t\leq T}
 \left(\|f(t)\|_{\mathrm{Bol},\beta}
       +\|\nabla_xf(t)\|_{\mathrm{Bol},\beta}\right)
       \leq C(A,B_0,\beta,T)<\infty.
\end{equation}
Fix, once and for all,
\begin{equation}\label{eq:pre-beta0}
 \beta_0=\beta/2.
\end{equation}
Thus all independent inputs $f(t)$ and their spatial Lipschitz
envelopes have a common bound with the fixed margin
$\beta-\beta_0$. Constants in \eqref{eq:pre-envelope} are independent
of the subsequent time-layer subdivision.
\end{proposition}

\begin{proposition}[Exact cell expansion]
\label{cell:expansion}
Let $R\subset S$ and let $A_0$ be the union of the blocks of
$\pi_0(S)$ meeting $R$.  For $R\ne\varnothing$, let $\mathcal P$ be
the collection of the other blocks of $\pi_0(S)$.  Then
\begin{equation}
 \mathsf H^I_{R,S}
 =\sum_{\mathcal U\subset\mathcal P}
      \mathsf K^I_{R,A_0\cup\bigcup\mathcal U},
 \label{eq:cell-subset-sum}
\end{equation}
and, as an equality of signed measures,
\begin{equation}
 \mathsf K^I_{R,A_0\cup\bigcup\mathcal U}
  =\sum_{\mathcal V\subset\mathcal U}
       (-1)^{|\mathcal U|-|\mathcal V|}
       \mathsf H^I_{R,A_0\cup\bigcup\mathcal V}.
 \label{eq:cell-boolean}
\end{equation}
Every coefficient is evaluated on its displayed input coordinates.
If $m=|S\setminus R|$, the number of diagrams in
\eqref{eq:cell-K} is at most $(C(1+m))^{Cm}$, with a universal $C$.
There is no partition of the roots in this count.
\end{proposition}

\begin{corollary}[Factorial normalization]
\label{cor:cell-factorial}
For the actual microscopic cloud and $r=|R|$, the cell identity is
written after relabelling the ordered roots as $R=\{1,\ldots,r\}$:
\begin{equation}
 \widetilde F_R(b)
  =\sum_{m\geq0}\frac{\mu^m}{m!}
       \mathcal T^I_{R,R\sqcup\{r+1,\ldots,r+m\}}
       \widetilde F_{r+m}(a).
 \label{eq:cell-factorial}
\end{equation}
The right side is interpreted with each finite Boolean coefficient
grouped before summing over $m$.  Equivalently, one may first restrict
the ensemble to $N\leq M$, apply the finite identity, and then let
$M\to\infty$.  No assertion of absolute summability of the
\emph{ungrouped} generation series is made here.
\end{corollary}

\begin{proposition}[Diagramwise factorization]
\label{cell:factorization}
Split the labels into $S=S_1\sqcup S_2$ and the roots into
$R=R_1\sqcup R_2$, where $R_i\subset S_i$.  Let $\gamma_i$ be a
diagram on $(R_i,S_i)$.  Define $\eta_I(\gamma_1,\gamma_2)$ to be the
indicator that every displayed particle trajectory of $\gamma_1$
has distance greater than $\varepsilon$ throughout $I$ from every
displayed trajectory of $\gamma_2$.  This includes detached groups
and includes the initial and terminal times.
For a single global diagram $\gamma$, define
$\eta_I(\gamma;S_1,S_2)$ by the same condition between its labelled
paths in $S_1$ and $S_2$, using their prescribed force-group flows.

On this indicator, merge the two root groups, and take the union of
the two batches at each generation, padding a finished list by empty
batches.  This gives a diagram on $(R,S)$.  Conversely, every nonzero
diagram term satisfying $\eta_I(\gamma;S_1,S_2)=1$ splits uniquely in
this manner.  Its detached groups necessarily belong to one $S_i$,
and its root flow splits over its two intersections with $S_i$.
Under this bijection the signed transport measures, with this
indicator imposed, agree with the tensor product of the two
diagram transport measures:
\begin{equation}
 \sigma(\gamma)w_I(\gamma)\mathsf H^I_{R,A}\,\eta_I
  =\eta_I\bigl[
       \sigma(\gamma_1)w_I(\gamma_1)\mathsf H^I_{R_1,A_1}
       \otimes
       \sigma(\gamma_2)w_I(\gamma_2)\mathsf H^I_{R_2,A_2}
             \bigr].
 \label{eq:cell-factorization}
\end{equation}
Summation over the bijection preserves this equality.  Factorial
weights split as
\begin{equation}
 \binom{m_1+m_2}{m_1}
       \frac{\mu^{m_1+m_2}}{(m_1+m_2)!}
   =\frac{\mu^{m_1}}{m_1!}\frac{\mu^{m_2}}{m_2!}.
 \label{eq:cell-factorial-split}
\end{equation}
\end{proposition}

\begin{definition}[Patternwise centered marginal]\label{cent:definition}
The centered marginal on pattern $\pi$ is
\begin{equation}\label{cent:definition-eq}
 E_\pi^\eps(t,Z_R)=\chi_\pi^\eps(Z_R)
 \sum_{A\subset S(\pi)}(-1)^{|S(\pi)\setminus A|}
 f_{S(\pi)\setminus A}(t,Z_{S(\pi)\setminus A})
 \widetilde F_{B(\pi)\cup A}^\eps(t,Z_{B(\pi)\cup A}).
\end{equation}
We set $E_\varnothing^\eps=1$. A nonsingleton block is always retained
as a whole; its individual labels are not centered.
\end{definition}

\begin{proposition}[Centering and inversion]\label{cent:identity}
For every $\pi$ and almost every $Z_R$,
\begin{equation}\label{cent:inverse}
 \chi_\pi^\eps\widetilde F_R^\eps(t)
 =\chi_\pi^\eps
 \sum_{A\subset S(\pi)}f_{S(\pi)\setminus A}(t)
 E_{\pi_A}^\eps(t).
\end{equation}
Both formulas hold for arbitrary factorial densities, without a
smallness or factorization assumption.
\end{proposition}

\begin{proposition}[Short-layer residual]\label{cent:residual}
Set $\beta_0=\beta/2$. There is $b_*>0$, depending only on the fixed
bounds in Proposition~\ref{pre:envelopes}, for which the following
holds. Suppose $b\leq b_*$, $K(\eps)\to\infty$, and
$J(\eps)\to\infty$ is a fixed power of $1+|\log\eps|$.
Then
\begin{equation}\label{cent:residual-def}
 r_{u,t}^{\eps}=f(t)-\mathscr G_{u,t}^{\eps,J,K},\qquad
 \sup_{\substack{0\leq u\leq t\leq T\\t-u\leq b}}
 \|r_{u,t}^{\eps}\|_{\mathrm{Bol},\beta_0}
 =:\eta_\eps\longrightarrow0.
\end{equation}
All the reference sums and residuals have uniformly bounded norms at
this one fixed exponent. The proof uses only short-layer tree
summability and two-body scattering.
\end{proposition}

\begin{lemma}[Augmented volume and the once-counted Gaussian]
\label{hist:gaussian}
For every fixed prescription $\Gamma$, the map from its $p$ source
coordinates to $\widehat Z(t)$ is one-to-one and volume preserving
outside null sets.  On $\mathcal D_\Gamma$,
\begin{equation}
 \sum_{i=1}^p|\widehat v_i(t)|^2\leq S+2Bp,
 \qquad
 \sup_{0\leq t\leq T}\sum_{\substack{i:\,i\text{ active at }t}}|v_i(t)|^2
       \leq S+2Bp.
 \label{eq:hist-mixed-energy}
\end{equation}
In particular, with $V(t)=(\widehat v_i(t))_{i=1}^p$,
\begin{equation}
 e^{-\beta_0 S}
 \leq e^{\beta_0Bp}
       e^{-\beta_0|V(t)|^2/2}e^{-\beta_0 S/2}.
 \label{eq:hist-split-gaussian}
\end{equation}
The same assertions hold at the last time, when the mixed coordinates
consist of the top coordinates and the departure coordinates of every
other label.  The exponent in \eqref{eq:hist-split-gaussian} is not
changed at a layer cut.
\end{lemma}

\begin{proposition}[Finite-term bound with its time factors]
\label{hist:basic}
Fix $A<\infty$ and the finite number $L$ of layers.  There is a
numerical exponent $d$ in the cell estimates such that, if
$J=\lceil P^Q\rceil$ with $Q>2dA$, all the following bounds hold
uniformly for $1\leq p\leq P^A$, for sufficiently small $\varepsilon$.
Put $n_j$ for the total additions in layer $j$, $h_j$ for its incoming
roots, and $q_j=h_j+n_j$.  After summing cell choices, cell diagrams,
and original parents, the absolute integral on the shell
\eqref{eq:hist-shells} is bounded by
\begin{align}
 &\eta_\Gamma C^p e^{-c rp}\mathsf S(h_0,E_r)
       \chi_\varepsilon^{m_*+o_*}(r+2)^{(m_*+o_*)/2}
       \prod_{j=1}^L\frac{b^{n_j}q_j^{n_j}}{n_j!}
 \nonumber\\[-2pt]
 &\hspace{22mm}\times
  \int_{\mathbb R^{3p}}
       \prod_{\substack{i:\,i\text{ an ordinary pin}}}
          \left(1+|w_i|^2+\frac{E_r}{q_{j(i)}}\right)^{1/2}
       d\gamma(V),
 \label{eq:hist-finite-bound}
\end{align}
where $d\gamma$ is a normalized product Gaussian of one fixed exponent,
the integral may retain the common indicator $|V|^2\leq E_r$,
and one may take
\begin{equation}
 \chi_\varepsilon
   = C P^{dA}\left(J^{-1/2}+\frac{\varepsilon J}{b}\right).
 \label{eq:hist-mesh-gain}
\end{equation}
Harmless increases of $d$ absorb the fixed extra powers occurring in
the finite diagrams.  Constants $C,c$ in
\eqref{eq:hist-finite-bound} do not depend on $L$ or on later rarity
cutoffs.  The threshold of sufficiently small $\varepsilon$ may
depend on the fixed $b=T/L$.

In particular, after summing layer occupancies and retained slots the
total finite integral of order $p$ is at most
\begin{equation}
 \eta_\Gamma C_L^p.
 \label{eq:hist-coarse-exponential}
\end{equation}
Its portion with $S>Rp$ is at most
\begin{equation}
 \eta_\Gamma C_L^p e^{-cRp},
 \label{eq:hist-source-tail}
\end{equation}
after changing $c>0$ and taking $R$ above a fixed constant.
These are estimates of finite independently enveloped terms, not
assertions about the actual process.
\end{proposition}

\begin{lemma}[A fixed-pivot forest]
\label{hist:pivot}
Fix a time $t_*$, a forest of $r$ edges on the $p$ labels, and
$\rho\geq\varepsilon$.  For one fixed force/lifetime prescription
whose required contacts connect every label to a top, the source integral
before multiplication by $\mu^{p-h_0}$, on $S\leq Rp$ with
$|x_i(t_*)-x_j(t_*)|\leq\rho$ on every forest edge is at most
\begin{equation}
 \eta_\Gamma C^p p^{Cp}\rho^{3r}
       \varepsilon^{2(p-r-h_0)_+}.
 \label{eq:hist-pivot-bound}
\end{equation}
More precisely, a stratum with $k$ final translation components has
the factor $\rho^{3r}\varepsilon^{2(p-r-k)}$, with $k\leq h_0$.
There is no factor equal to the number of cells in this geometric
bound.
\end{lemma}

\begin{proposition}[Extensive simultaneous crowding]
\label{hist:crowding}
Fix $A,Q,L,R$ and $\delta>0$.  Among independently enveloped finite
histories with $p\leq P^A$ and $S\leq Rp$, the activity-normalized integral
for which at some time at least $\delta p$ displayed labels have a
companion within $\rho=\varepsilon^{.85}$ is bounded by
\begin{equation}
 \eta_\Gamma P^{C_{A,Q,L,R}p}
       \varepsilon^{.275\delta p-1}.
 \label{eq:hist-crowding-explicit}
\end{equation}
For $\delta p\geq8$ this is at most
$\eta_\Gamma\varepsilon^{.1\delta p}$ for sufficiently small
$\varepsilon$, uniformly in the stated range of $p$.
\end{proposition}

\begin{lemma}[Premature contacts in original coordinates]
\label{exp:rerouting}
Outside the original compact-parameter, crowded-parent, and multi-addition
exceptions, the contribution with a specified set of $k$ singleton cells
having a premature contact has bound
\begin{equation}
\label{exp:reroute-bound}
 C_L^p\bigl(p^C\varepsilon^c\bigr)^k.
\end{equation}
Consequently an extensive number of premature contacts has arbitrarily
strong exponential suppression.  The remaining premature births may be
marked irregular before selecting terminal subtrees.  No global
reparenting multiplicity is included or needed in this estimate.
\end{lemma}

\begin{proposition}[Causal exposure for mixed prescriptions]
\label{exp:exposure}
Fix an admissible mixed whole-cell prescription with $p\le P^a$ labels and
a total energy budget $\mathcal K\le Rp$.  Fix a collection of $k$ disjoint
regular terminal trees as in Lemma~\ref{exp:terminal}.  Sum the absolute
activity-normalized chart integrals over the event that every selected tree has a
first defect.  The result is bounded by
\begin{equation}
\label{exp:exposure-bound}
 \mathcal A_p\,(pJ)^{C p}\bigl(p^C\varepsilon^c\bigr)^{k/2},
\end{equation}
The factor $(pJ)^{Cp}$ includes cell-segment choices.  Constants may
depend on the fixed layer count, compact cutoffs, $M$, and $R$.
\end{proposition}

\begin{lemma}[Retained-slot entropy]\label{close:entropy}
Suppose a term retains $k_j$ slots among $q_j$ available slots at
successive cuts. Put $Q=\sum_jq_j$ and $H'=\sum_jk_j$. Then
\begin{equation}\label{close:slot-bound}
 \prod_j\binom{q_j}{k_j}
 \leq\binom{Q}{H'}
 \leq\exp\left\{H'\log\frac{eQ}{H'}\right\}
 \quad (H'>0).
\end{equation}
In the history expansion $Q\leq p+C H$ and $H'\leq C H$, up to a
fixed number of choices per retained slot. Consequently, when $H\leq\delta p$,
the logarithmic selection cost is at most
\begin{equation}\label{close:entropy-small}
 C\delta p\left(1+\log\frac1\delta\right).
\end{equation}
For general $H\leq Lp$, its cost is at most $C_L^p$.
\end{lemma}

\begin{lemma}[Energy and the short-layer factors]\label{close:energy}
For a completed history with the above counts, the parent, time,
and velocity factors in Proposition~\ref{hist:basic}, before
retained-slot and spatial losses, have total integral at most
\begin{equation}\label{close:energy-factor}
 (C b\sqrt L)^p
 \exp\{H+h_0\log_+(1/b)\},
 \qquad b\leq1.
\end{equation}
The constant $C$ is independent of $L$. A fixed part of the source
Gaussian remains available for the spatial estimates.
\end{lemma}

\begin{lemma}[Integrated amplification and bad clouds]
\label{close:amplification}
Consider a finite completed block containing at most $M$ labels
and acting on an input signed array in integrated total variation.
For $M$ and $J$ bounded by fixed powers of $P$, its operator norm
is at most
\begin{equation}\label{close:raw-amplification}
 \exp(C_LMP).
\end{equation}
The same bound holds for the pattern-summed centered norm of
\eqref{cent:centering-norm}. If a physical layer is stopped below
$K$ labels, the contribution of a
microscopic event $\mathcal A$ to the exact observable minus its
completed physical below-$K$ expansion is at most
\begin{equation}\label{close:bad-discard}
 \exp(C_LKP)\,\mathbb P(\mathcal A)^{1/2},
\end{equation}
provided its upper root count is less than $K$. This discard is
made before estimating any overshoot.
\end{lemma}

\begin{proposition}[Actual witnesses and layer remainders]
\label{close:tails}
With the preceding schedule, for sufficiently small
$\varepsilon$ and every $1\leq j\leq L$,
\begin{equation}\label{close:actual-tail-bounds}
 \mathbb P\bigl(\mathcal B_j(D_j)\bigr)\leq e^{-8D_j},
 \qquad R_j\leq e^{-8K_j}.
\end{equation}
The estimates use the original Newtonian process, without
conditioning it to stay in a good set.
\end{proposition}

\begin{lemma}[Prescribed velocity and comparison]\label{lem:realization}
Let $U$ be a smooth divergence-free velocity on
$[0,\infty)\times\T^3$ with $U(0)=0$. Define
\begin{equation}\label{eq:residual}
 F=U_t+(U\cdot\nabla)U-\nu\Delta U.
\end{equation}
Then $(U,0)$ is a global smooth solution of \eqref{eq:NS} with force
$F$, unique in the classical class on every finite time interval.
If $U$ has zero spatial mean, so does $F$.
\end{lemma}

\begin{corollary}[Periodic forcing from time zero]\label{cor:periodic}
There is also an effective construction with zero initial velocity on
$\mathbb T^3$, a smooth mean-zero force of period one in time with
all mixed derivatives bounded, and the fixed particle event of
Theorem~\ref{thm:main}.
\end{corollary}

\begin{lemma}[Smooth scalar evolution with integrable tails]
\label{cbe:scalar-lemma}
Equation \eqref{cbe:scalar} has a global smooth solution.  Every
space-time derivative is continuous in time with values in
$C_0(\mathbb R^2)\cap L^1(\mathbb R^2)$, where $C_0$ denotes
continuous functions tending to zero at infinity.  Furthermore,
\begin{equation}\label{cbe:mass}
 \rho\ge0,\qquad
 \mathcal M(t):=\int_{\mathbb R^2}\rho(t,X)\,dX=\theta(t)\le1.
\end{equation}
\end{lemma}

\begin{lemma}[Two explicit heat bounds]\label{lem:heat-bounds}
For either $(d,H)$ in~\eqref{eq:two-constants}, the unit two-torus
heat kernel satisfies
\begin{equation}\label{eq:heat-bound}
 K(\tau,Z)\le H
 \quad\hbox{if }\tau\ge1
 \quad\hbox{or}\quad\dist_{\T^2}(Z,0)\ge d.
\end{equation}
\end{lemma}
